INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p614558-ee398', 'stk-the_o_e', 'EE 398', 'info', '{"desc": "عزيزي The Golden\nأنا طبقت في الشركة، وتخصصي هندسة كهربائية، الشركة للمهندسين الكهربائيين جداً ممتازة، تديك خبرة طيبة في مجال الـ(Switchgear & Protection). وتمنحك الفرصة لتعلم الكثير من الأشياء المفيدة التي ستشعر بقيمتها عندما تتقدم للشركات للتوظيف وتجري مقابلات شخصية. ستشعر بأنك تحمل كماً هائلاً من المعلومات كفيل بأن يجعل اي مقابله شخصية سهلة بالنسبه لك.\nالشركة تتميز باهتمامها بالمتدرب عن طريق الحاقه بدورات متعدد وفي مجالات متنوعة ومفيدة جدا مع الحصول على شهادة لكل دورة الى جانب برنامجهم التدريبي المنظم منذ بداية فترة التدريب وحتى نهايته.\nالشركة تنقسم الى عده اقسام\nقسم التصميم\nقسم التحكم بالجوده\nقسم الخدمات\nقسم إدارة المشاريع\nقسم التحكم والقياس\nقسم إدارة الجوده (غير التحكم بالجوده،الاول تكنيكال اما الثاني اداري)\nطبعا الشركة تاخذ مهندسي تحكم وقياس وشغلهم جدا ممتاز وبتستفيد جدا جدا.\nاذا كان تخصصك هندسة كمبيوتر فلا افتيك فيما لا اعلم حقيقةً ولكني لم ارى ولم اسمع ان الشركة اخذك طالب كمبيوتر للكواب ولكن لما كنت هنا صار شيئين:\nاتوظف واحد تخصصة هندسة كمبيوتر من جامعة الملك سعود، شغلوه في الآي تي، قعدله فتره كده وطفش وساب الشركة لانهم كانو بيشغلوه شغل مشي حالك يعني صلح الكمبيوتر هذا … في برنامج يبغاله تثبيت روح ثبته … يعني اشياء زي كده\nاتوظف واحد ثاني (سوري ماادري اردني) هذا اشتغل في قسم التصميم (اشتغل شغل مهندسي الكهرباء شغل ماله اي علاقه بتخصصه كمان بس هذا ماادري قاعد ولا راح)\nبالنسبه لتخصص هندسه الكمبيوتر انا بصراحه لا انصح بشنايدر لان في شركات افضل منها في هذا المجال بكثير ويقدر الطالب يستفيد منها اكثر\nاما بالنسبة لطلاب الكهرباء والتحكم والقياس فاقول اتوكل على الله وانت مطمئن وان شاء الله ماراح تندم\nنسيت اذكر ان الشركه تديك في فترة الكواب 4000 ريال +تأمين طبي +تأمين سيارة +تامينات اجتماعية +عقد تدريب منتهي بالتوظيف\nوبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/88714/4", "user": "THE_O_E", "ts": 1274732243000, "tid": 88714, "pn": 4}}', 1274732243000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1483097-ee398', 'stk-abus3od', 'EE 398', 'info', '{"desc": "عليكم السلام\n\nاذا مقابلتك فالدمام الصناعية الثانية فالدمام فاللي بيسوي معك المقابلة مدير الموارد البشرية شمري ومعاه السكرتيره تكتب ملاحظات\n\nمقابلتي كانت على التدريب التعاوني عندهم وكانت سهلات بالانجليزي تكلم عن نفسك ومشروعك ,وليه معدلك نازل فالدبلوم وعالي فالبكالوريوس ووش تعرف عن الشركة وسالني اسالة بيسك عن الكهرباء بما ان تخصصي يندرج فالكهرباء زي وش قاونون اوم , حالة التيار في حال كانت الدائرة توازي او توالي, قوانين CDR , VDR , KVL وسألني وش الحساسات اللي ممكن موجودة على خط الانتاج (Ultra sonic, proximity) ولما خلصت المقابلة قال خلاص عديت مبروك\n\nومثل ماقلت المقابلة كانت للتطبيق عندهم ويمكن تختلف اذا كانت توظيف مادري\n\nعموما اذا تخصصك ميكانيكا توقع 95% بتجيك اسالة تكنيكال راجع زين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/al-qaryan/178052/2", "user": "abus3od", "ts": 1510155484000, "tid": 178052, "pn": 2}}', 1510155484000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1380449-ee398', 'stk-3boody830', 'EE 398', 'info', '{"desc": "form the grade distribution form:\n\nNote: If you start your coop in the summer, then the summer coop coordinator will act as your Coop Advisor. By the end of the summer and the beginning of the Fall semester, you will be assigned a specific coop advisor.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-advisors-for-ee/162735/4", "user": "3boody830", "ts": 1403007576000, "tid": 162735, "pn": 4}}', 1403007576000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p563986-ee398', 'stk-imported_mis_uoh', 'EE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته،\n\nكيف حالكم أخواني الأعزاء\n\nقيل \" ما خاب من استخار ولا ندم من استشار\"\n\nلذا أنا حاب آخذ رأيكم بموضوع وهو:\n\nأنا بإذن الله على الصيف القادم راح أكون في مرحلة التدريب التعاوني ومتحير بالشركات اللي أتدرب عندها\n\nوأبي مشورتكم بخصوص الشركات هذي :\n\nسابك - الجبيل\nالشركة السعودية للكهرباء - الدمام\nشركة الإتصالات السعودية - الدمام\n\nعلماً بأن تخصصي هو mis …\n\nوألف شكر لكم مقدماً ، وجعلها الله في ميزان حسانتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/85258/1", "user": "imported_MIS_UOH", "ts": 1268389395000, "tid": 85258, "pn": 1}}', 1268389395000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1434368-ee398', 'stk-eng.m.m', 'EE 398', 'info', '{"desc": "السلام عليكم انا ادراتي\nrefinery and ngl\nفي الرياض down stream\nوش رايكم فيها انا مش من سكان الرياض فهل يعطون سكن (بدون خصم بدل السكن) وقت التدريب كواب\nوهل القسم مفيد ك تطوير وترقيات للمهندس الكهربائي\nارجو الافادة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/aramco-cdpne/170741/31", "user": "eng.m.m", "ts": 1448358451000, "tid": 170741, "pn": 31}}', 1448358451000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1505254-ee398', 'stk-n2sser', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nتسجيل الكووب الاسبوع الجاي و ماني داري ايش الكورسات اللي انزلها لان فيه ثلاث كورسات\n( EE 350 , EE 351 , EE 352 )\nفلو احد يقدر يفيدني اكون له من الشاكرين.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/180924/1", "user": "n2ssEr", "ts": 1548233417000, "tid": 180924, "pn": 1}}', 1548233417000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p31835-ee398', 'stk-hadi', 'EE 398', 'info', '{"desc": "الحال من بعضه\n\nيا أخ ليث\nهذه ليست مشكلتك لوحدك فمعظم طلاب ال coop ما يسوون شيء.\nعندك أنا تخصصي هندسة كهربائية وإنتتهت شهرين وأنا في (أرامكو) ما سويت شيء. ( الحال من بعضه).\nوالله يعيننا…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/25743/10", "user": "hadi", "ts": 1062847942000, "tid": 25743, "pn": 10}}', 1062847942000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1047522-ee398', 'stk-not_yet', 'EE 398', 'info', '{"desc": "أنا أخذت معاهم كوأب, هندسة كهربائية.\n\nالطريقة: لابد من أن تضغط عليهم إن كنت تريد أن تعمل معهم, لأنه ما أحد يطلب منك شيء أبدا,\n\nبالتالي انت تضغط عليهم صح, إلى أن يجدوا لك مكان بينهم.\n\nالموقع:-\n\nمخرج 18, انت ماشي في الدائري الشرقي رايح جنوب, طريق الخرج\n\nبعد إسكان البحرية, وبعد النفق الثالث, تجيك لوحة مكتوب عليها سابك (لوحة كبيرة على اليمين)\n\nعلى طول ادخل الخدمة, وبعده يجيك تقاطع رح يمين, تجيك بوابة الصناعية,\n\nتشوف محطة إسناد (الزاوية شمال غرب), يجيك تقاطع كبير وتشوف بوابة الصناعية,\n\nرح يسار وتصير المحطة على يدك اليمين, أول لفة يمين, ثالث لفة يسار,\n\nتحصل الشركة على يدك اليسار, باب حديد أخضر. بالتوفيق\n\nتمام؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/126596/2", "user": "Not_Yet", "ts": 1338298118000, "tid": 126596, "pn": 2}}', 1338298118000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1065500-ee398', 'stk-user1508', 'EE 398', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nأنا خريج هندسه كهربائيه تطبيقيه\n\nو هذي تفاصيل مقابلتي قبل سنه تقريبا … كتبتها في احد المواضيع القديمه\n\nطبعا كان موعد مقابلتي الساعه 2 و نص ظهرا … و وصلت على الموعد\n\nو لكن للأسف ما دخلوني للمقابله الا الساعه 3 و خمس دقايق … بحجة انه كانوا يقابلون واحد قبلي\n\nو الله لا يوريكم حالتي من التوتر بسبب طول الانتظار\n\nأول ما دخلت … استقبلني 3 أشخاص على طاوله هم في جهه و انا في جهه\n\nسلموا علي و عرفوا بأنفسهم … و طلع اللي بالنص هو المانيجر تبع الباور سيستم ديبارتمنت و الاثنين الاخرين واحد اسبيشاليست و الاخر سينير انجينير\n\nاول شيء طلبوا مني اني اتكلم عن نفسي بشكل عام و عن دراستي و أهم المنجزات و المشاريع اللي حققتها و كله طبعا بالانجليزي\n\nبعد ما أخرجت كل ما عندي … بدوا بالاسئله\n\nما هي أهم كورسات البور اللي خلصتها ؟ تكلم عن البروسيس تبع الباور سيستم من بداية انتاج الكهرب الى حين وصوله للودز , وش أهم الديفايسز الموجوده في المحطات الكهربائيه و نحوها\n\nو كذلك سألوني عن مشروع التخرج\n\nو بما اني طبقت الكواب في سكيكو … سألوني عن الديبارتمنتس اللي طبقت فيها و وش أهم الاختبارات اللي سويناها و البروجكتات خلال فترة الكواب\n\nثم سألني المانيجر سؤال خبيث شوي\n\nقال لي : لو جاك اوفرين بنفس طبيعة العمل و بنفس الساليري واحد من سكيكو و واحد من أرامكو … أيهم تختار و ليه ؟\n\nبعدين سالوني عن اذا كنت أرغب بالعمل في المناطق البعيده … و عندما جاوبتهم بدأوا يناقشوني في الاجابه\n\nو في نهاية المقابله سألني الاسبيشاليست سؤال غريب شوي و ما توقعته … قال لي : أنت أخذت كورس\n\nEngineering Economics ?\n\nو قلت له معي بهذا السمستر\n\nقال لي : تلكم لي عن الاشياء اللي أخذتوها في الكورس الى الان\n\nو بالنهايه بدأ المانيجر يشرح لي أهمية الديبارتمنيت و أنواع الاعمال اللي يقومون بها ووو … الخ\n\nو سألني هل عندك أي استفسار\n\nو انتهت المقابله … و سلمت عليهم و طلعت\n---------------------------------------\n\nثم رافقني الشخص اللي كلمني بالتلفون الى باب مركز التوظيف\n\nو سألته : وش البروسيس اللي بتصير بعد كذا ؟\n\nقال لي : بعد اسبوعين تقريبا بنرد عليك اذا ما تمت الموافقه او لا … و اذا تمت الموافقه لازم تجي علشان تقرأ العقد و تتطلع عليه , و لك 7 ايام علشان تقرر , و اذا وافقت يبقى لك الفحص الطبي\n\nو يوم رجعت للغرفه وجدت ايميل واصلني من أرامكوا فيه 3 اختبارات اون لاين\n\nواحد لوجيكال و واحد فيربال و واحد نيوميريكال\n\nو مطلوب مني انهاء كل قسم خلال 45 دقيقه … و لي الى 28 ابريل لاتمام هذه الاختبارات\n\nو بصراحه الى الان ما سويتها\n\nهذا بالظبط ما صار لي … و ارجو منكم الدعاء لي بالتوفيق و السداد\n\nو جزاكم الله خير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/128546/5", "user": "user1508", "ts": 1341833664000, "tid": 128546, "pn": 5}}', 1341833664000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1336458-ee398', 'stk-user5808', 'EE 398', 'info', '{"desc": "السلام عليكم,انا طالب كواب الكتريك في سابك (شركة كيميا),غالبا مهندسي الكهرب راح يشتغلون كانسترومنت على حسب كلام المنجر حقنا(من 8 مهندسين كهرب ستة انسترومنت واثنين بس الكتركال)\nطبعا انا اعتبر جديد على العمل حتى الان بس اغلب شغل الانسترومنت على dcs & plc والفلفات والترانزيستورز والترانزميترز بشكل عام,اما الكهرب الى الان مادري عنهم لاني راح اشتغل معهم في اخر شهرين من الكواب ان شالله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/157688/7", "user": "user5808", "ts": 1393870114000, "tid": 157688, "pn": 7}}', 1393870114000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p352403-ee398', 'stk-thamer_al-fakeeh', 'EE 398', 'info', '{"desc": "Dears\n\nGE is offering a coop opportunity for the following majors:\n\nISE\nLocation: KSA-Dammam\nME\nLocation: Dammam\nEE\nLocation -Damma\nFinance\nLocation: Bahrain\nRequirements:\n\nExcellent communication kills\npassion for learning and working in multinational professional enviroment\nGPA 3.0/4.0\nmajored in ME,EE, ISE or Finance\nif you are interested to work with the world’s most admired company General Electric, please send your CV titled with which opportunity you are interested in to\n\nThamer.al\\-fakeeh@ge.com\n\nBest of Luck!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-opportunity-in-general-electric/69540/1", "user": "Thamer_Al-Fakeeh", "ts": 1232142802000, "tid": 69540, "pn": 1}}', 1232142802000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1464899-ee398', 'stk-user8581', 'EE 398', 'info', '{"desc": "**فرص تدريب (COOP) في الرياض في شركة Cisco **\n\n: مدة التدريب 7 أشهر\nرابط التقديم\nInternship - Technical & Business Saudi Arabia\n\nالتفاصيل + التخصصات المطلوبة\n\nInternship - Technical & Business Saudi Arabia\nApply now\nDate: Dec 19, 2016\n\nLocation: Riyadh, AR Riyad, Saudi Arabia\n\nAdditional Location(s) or Information: Start Date: February 2017 Duration: 7 Months\nJob Category: Sales\nLevel of Experience: Intern\nRequisition #: I1025795\n\nJob Description:\n\nStart Date: February 2017\nTraining Location: Saudi Arabia\n\nWhy You’ll Love Cisco\n\nEverything is converging on the Internet, making networked connections more relevant than ever before in our lives. Our employees’ revolutionary ideas impact everything imaginable - from entertainment, retail, healthcare, and education, to public and private sectors, smart cities, smart cars, and everyday devices in our homes. Here, that means you’ll take creative ideas from the drawing board to powerful solutions that have real world impact. You’ll interface with Cisco leaders, partner with experienced mentors, and develop incredible relationships with colleagues who share your interest in connecting the unconnected. You’ll be part a team that cares about its customers, enjoys having fun, and you’ll take part in changing the lives of those in our local communities. Come prepared to be inspired.\n\nNextGen Leaders Program:\n\nThis is a 7 months length internship program that opens for various tracks in Business and Technology. Gain valuable skills with global qualifications. A successful NextGen Leaders Intern will expand their networking knowledge and be trained to collaborate with Cisco sales and engineering professionals to provide solutions for our customers. Learn from top Cisco experts in a unique setting among your peers. The NextGen Leaders Program offers a global environment of on-the-job training that will prepare you for a successful career. Gain hands-on education and experience with leading-edge technology.\n\nWhat are the different Tracks:\n\nWe are opening for limited seats on the below tracks:\n\n• Sales\n• Systems Engineering\n• Advanced Services\n• Program Management Support\n\nWhat You’ll Do:\n\nFor the first month of the program, you’ll be acquiring knowledge focusing on the latest technology advancements, including Cisco architectures, solutions, products, and competitors. Over the following 6 months, you’ll advance into an on-the-job-experience within your track. Actively involved in work opportunities as well as shadowing professionals and virtual learning.\n\nWhat you need to be eligible:\n\n• You must be in a position to graduate from your degree by the start date of the program, or have the internship as the last prerequisite to graduate.\n• You must be available full time for the period of the program.\n• You will preferably hold a degree such as Bachelor’s (BS/BA/etc.) or master’s degree in:\nElectrical, Computer, or Networking Engineering; Computer Programming; Information Technology; Management Information Systems; Computer Science; Business and Management; HR ; Finance; Marketing and any other Economics related degrees.\n• You are fluent in English and the Arabic.\n• You must be a Saudi National.\n\nAbout Cisco:\n\nThe Internet of Everything is a phenomenon driving new opportunities for Cisco and it’s transforming our customers’ businesses worldwide. We are pioneers and have been since the early days of connectivity. Today, we are building teams that are expanding our technology solutions in the mobile, cloud, security, IT, and big data spaces, including software and consulting services. As Cisco delivers the network that powers the Internet, we are connecting the unconnected. Imagine creating unprecedented disruption. Collaborate with like-minded innovators in a fun and flexible culture that has earned Cisco global recognition as a Great Place To Work. With roughly 10 billion connected things in the world now and over 50 billion estimated in the future, your career has exponential possibilities at Cisco.\n\nJob Type: Intern/Co-Op\nOpportunity Category: Internet of Everything, Cloud, Video, Collaboration", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/44", "user": "user8581", "ts": 1482249076000, "tid": 174980, "pn": 44}}', 1482249076000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1233751-ee398', 'stk-development_eng', 'EE 398', 'info', '{"desc": "أعزائي طلاب جامعة الفهد … المقدمين على التدريب التعاوني (كوأب)\n\nالسلام عليكم و رحمة الله و بركاته\n\nنعلن عن فرصة شاغرة لأحد التخصصات التالية :\n\nالهندسة الكهربائية (AEE)\n\nهندسة الحاسب (COE)\n\nهندسة التحكم (CISE)\n\nللراغبين ، الرجاء إرسال السيرة الذاتية على : rawabijobs@yahoo.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/145927/1", "user": "Development_Eng", "ts": 1370854001000, "tid": 145927, "pn": 1}}', 1370854001000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1451976-ee398', 'stk-faisalcom2008', 'EE 398', 'info', '{"desc": "بالتوفيق ان شاء الله يا اخوي\nانا سويت مع القسم هذا مقابلة في يوم المهنة الماضي\nالمقابلة كانت خفيفة بالبداية تكلم عن نفسك ومشروع التخرج والتدريب التعاوني ثم سألوني كم سؤال تكنكال في تخصصي (هندسة كهربائية) اخر شي اعطاني ورقة وقلم كلي اكتب اي شي بحدود ثلاث اربع سطور اخر شي علمني عن القسم ومناطق عملهم (كلها نائية تقريبا). موفق ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/171072/11", "user": "faisalcom2008", "ts": 1466031151000, "tid": 171072, "pn": 11}}', 1466031151000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p301748-ee398', 'stk-user1823', 'EE 398', 'info', '{"desc": "يارجال…صلي على النبي…\n\nتراك مبالغ و مهول الأمر بقوة!\n\nأولا: جون 2008 مو بعيد…بكرة تكمل شهرين من يوم تخرجك…في ناس تقعد ستة الى تسعة شهور بدون عمل…اذا وصلت الى هذي الفترة وقتها طبيعي أن تقلق 🙂\nثانيا: الظاهر و الله أعلم…و من تجربة أيام الكوأب…عندك مشكلة في السي في…يا ان الهدف من السي في غير واضح…او انه غير جذاب كفاية لمسؤولي التوظيف\nثالثا: بما انك كهرب…خليني اخمن…الهدف حقك (ارامكو-سابك-الكهربا)…الثلاثي المرح هذول ليلهم طويل…و ما يردوا بسرعة…لما تنساهم تتفاجأ بإتصال منهم\nرابعا: انت من جدك؟ تعرف يعني ايش خريج 2.8 من البترول؟ اذا انت ما لقيت شغل مين يلاقي؟\n\nفي الرد الجاي راح اكتب لك قصتي من ايام الكوأب الى ان تخرجت…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/65561/4", "user": "user1823", "ts": 1219241247000, "tid": 65561, "pn": 4}}', 1219241247000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1402729-ee398', 'stk-user2352', 'EE 398', 'info', '{"desc": "الله يعافيك\n\nفي ينبع أتوقع عندك شركات مرافق والكهرباء تقدر تحصل لك فرصة تدريب كوأب بنفسك بتجهيز cv مع ورقة التعريف والترشيح من ادارة التدريب مع نموذج فرصة تدريب تعاوني ،،\nوسابك وأرامكو تحتاج لك واسطة ومعرفة فيها 🙂\nوعلى معدلك هذا انصحك بالكوأب في أي شركة تتوفر لك\n\nوالله يكتب لك اللي فيه خير إن شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/165832/4", "user": "user2352", "ts": 1411489954000, "tid": 165832, "pn": 4}}', 1411489954000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1478467-ee398', 'stk-instrument', 'EE 398', 'info', '{"desc": "وعليكم السلام ورحمة الله\nالله يعطيك العافية\nمعلومات ممتازة لكن سويت مقابلة مع ادرة المشاريع عندهم قبل ردك وماكنت عارف عن الشركة شي لكن مدير مشروع اعطاني فكرة بسيطة عن الشركة والشركة تتبع مجموعة الراشد وبعد يقول ان المشاريع او الشغل مافي واجد!\nتقريبا ساعه سواليف\nبعد هالساعة قالي كلم بالجوال كلمني سعودي مدير مدير المشروع على كلام مدير المشروع\nس1.\nايش وداك الصين؟ :office_worker:\nس2.\nتشتغل بالحد الجنوبي :ninja:\nوشوي دردشة بشكل ودي\nبعدين قالي خلاص بنودي اوراقك الى الاتش ار غدا\nاعطوني اربع اوراق قالو عبيها وجيبها اليوم الثاني\n\nاليوم الثاني قبل ماروح اودي اوراقي وشهاداتي, اتصل علي مدير المشروع العربي وقال كم تبغ راتب,قلت بما انه على قولك الشغل ماش والوضع لك عليه اساسي8000 اعتقد مقبول عندي\nقال شو قليل هذا في حقك 😍\nالمهم واكتب في النموذج الراتب المتوقع 13800 اساسي 🤠\nورحت له المكتب واعطية الاراق والشهادات وقاعد يتفحص في الاوراق الي وهو يقولي لي كاتب13800 ووجه كنه متمعر 😞:santa_1:\nانا انخرشت منه وطوالي مخرج7\nقلت قصدي مع البكج كامل 😡\nقلت خليني اغيره\nقال لا خلاص خليه كذا :zipper_mouth_face:\nوشكله بيمسكني الكوبري المعلق!\nالمهم اتوقع والله اعلم سوف استبعد علشان الراتب والحمدلله على كل حال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-s-e-m/177343/4", "user": "Instrument", "ts": 1502549078000, "tid": 177343, "pn": 4}}', 1502549078000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1529613-ee398', 'stk-user11095', 'EE 398', 'info', '{"desc": "بالنسبة لهذي الدورات اشوف انها مادية ومفيدة للشركات اكثر من المتقدم.\n\nفالغالب التدريب التعاوني كافي ويغطي نفس المواضيع المذكورة لو فرضنا انه بيكون في التحلية … وقس على ذلك المواضيع المتعلقة لو كانت في شركة ثانية كالكهرباء وغيرها…\n\nرأيي اذا انك انسان عاطل وتدربت تدريب تعاوني وعندك هالمبلغ 10 آلاف فاشوف انك تستثمره في الشهادات الاحترافية فوجودها في سيرتك اقوى من هالدورة, او تنتظر انك تتوظف وتحطها في برنامج ماجستير في لبترول تكلفته نفس هالمبلغ تقريباً او شي يجلب لك المنفعه المادية مثل البيع والشراء عن طريق الانترنت.\n\nاذا كان برنامجهم موعود بالتوظيف فهنا الموضوع مختلف تماما واشوف تروح لهم بدون تفكير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/183834/5", "user": "user11095", "ts": 1619197455000, "tid": 183834, "pn": 5}}', 1619197455000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1325656-ee398', 'stk-s.u.l.t.a.n', 'EE 398', 'info', '{"desc": "تختلف طبيعة الاسئلة و ليست ثابته ، لكن مثل ما ذكر الاخ المهندس فوق ، فيه اسئلة شائعه و لو حضرت لها كويس بتشيل عليك حمل …\n\nتكلم عن نفسك ؟\n\nتكلم عن الكواب او السمر تريننق ؟\n\nمشروع التخرج ؟\n\nو بما انهم توزيع ، ف بيسالونك عن الترانسفورمر و طريقة عمله و الببروتيكشن و من هالقبيل ؟\n\nخلك واثق من نفسك مقابلات الكهرباء سلسه و مريحه …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/156322/3", "user": "S.U.L.T.A.N", "ts": 1391362449000, "tid": 156322, "pn": 3}}', 1391362449000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1365023-ee398', 'stk-fa7ad', 'EE 398', 'info', '{"desc": "و الله ياشباب انا و اخوياي كلنا ندرس نفس الكورسات و نفس الخطه بالضبط في جامعة حايل بعضهم مكتوب لهم ابلايد و بعضهم مكتوب ساينس و الله العظيم كلنا درسنا نفس الكورسات بالضبط و في نفس الكلاسات و وكلنا عملنا كواب سبع اشهر ولما رجعنا عملنا سنير بروجكت و الله ولما تخرجانا و كتوب لنا حاصل على شهادة الهندسة فس العلوم الكهربائيه يعني ساينس ولا فهمت وش الفرق بينهم الى يومكم هذا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/161141/10", "user": "fa7ad", "ts": 1400166231000, "tid": 161141, "pn": 10}}', 1400166231000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p604028-ee398', 'stk-user4067', 'EE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nيا شباب بالله اذا احد عنده خلفية اكيدة عن المواد الضرورية لأنهائها حتى اتمكن من اخذ الكوااب.\n\nانا EE applied\nلأنو في الفلو تشارت الموجود في الموقع الحين يقول أن ENGLSH 214 هي الوحيدة المطلوبة. وهذا يثير الشك.\n\nوشكرا لكم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/87938/1", "user": "user4067", "ts": 1273574423000, "tid": 87938, "pn": 1}}', 1273574423000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1347875-ee398', 'stk-user9645', 'EE 398', 'info', '{"desc": "وعليكم السلام ورحمة الله\n\nأخوي Al-Furhud\n\nاول شي اتمنى ان الله يوفقك ويسهل لك أمرك\n\nواذا جتك فرصه افضل في شركة مثل GE , ABB , SLB , Schnider لا تتردد\n\nوشوف ردي في احد المواضيع هنا\n\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=120658\n\nقبل لا اقولك عن الكوأب حط في بالك ان “أغلب” الشركات يهملون الطلاب في الكوأب\n\nوهذا شي جدا طبيعي , بحكم انشغال الموظفين وكثرة طلاب التدريب التعاوني او الصيفي\n\nلكن بالنسبة لشركة الكهرباء انا اخذت الكوأب عندهم , وحالتي كانت كالآتي :\n\nكان عقدي اني اشتغل معهم بقسم الهندسة\n\nدوامت اول يوم متحمس وكالمتوقع عطاني كتاب اطول مني وقال اقراه ,\n\nمع العلم انه قالي تداوم او ما تدراوم كيفك , بالعربي الرجال مشغول وصرفني 😆\n\nوكردت فعل طبيعي رحت لمكتب فاضي وحطيت الكتاب وقفلته ورجعت له ع طول وقلتله خلصت 😍\n\nقال تمزح !!\n\nقلت شوف يا عزيزي انا اخذت دروس وكتب بالجامعه بما فيه الكفايه وجيت هنا اشتغل\n\nقالي اياها للاسف بصريح العبارة هنا مافي شغل كثير ولا راح تستفيد كثير في قسمهم وانهم مشغولين\n\nبقيت فتره على هالحاله بعدين طفشت ورحت لقسم الصيانه , وكلمت مديرهم الله يوفقه في كل وقت وكل مكان\n\nوشرحت له الوضع وقلتله ابي اشتغل واستفيد بالعربي ,\n\nقالي عندك استعداد تدوام الساعه 4 , قلت اكيد\n\nوبقيت تقريبا 3 شهور على هالحاله , اداوم قبل العالم وكل يوم بمكان وميدان\n\nبس طبعا مو يوميا 4 , لو مهبول ما دوامت كذا\n\nاحيانا يعطوني راحه ويقولون تعال 8 في المكان الفلاني\n\nالهدف كان الفائدة مو التزام الوقت لانك مو موظف , انت متدرب فتره وماشي 👍\n\nواستفدت كثير , ولكن الفائدة جت لاني نشبت لهم\n\nوكان دوامهم ملائم جدا , لانهم يداومون بدري بسبب الحراره ترتفع بالنهار فعشان كذا\n\nتلقاني مداوم 4 او 5 الفجر وطالع البيت الساعه 12 الظهر 😏\n\n… بعدها رحت لقسم المشاريع وهذا كان فائدة أكبر خصوصا لتخصص POWER\n\nلكن يحتاج له وقت اطول ,\n\nنصيحتي لك انشب اذا فعلا بتستفيد وقلهم انك حريص وراح تلقى شباب والله مثل العسل وبيساعدونك معهم بالراحه\n\nالصيانه بالمختصر قسم مفيد ولكن حاول ما تجلس بمكان واحد ,\n\nروح لقسم الضغط المتوسط والعالي , لأن هالشيئين بيخدمونك بالتقرير بنهاية الكوأب ومن ناحية التخصص راح تكتشف في بعض مواد LEVEL 4 انه مهمه .\n\nواعتذر عن الاطاله ولكن اتمنى لك ان شاء الله التوفيق ولكل الباقين ,\n\nواي استفسار ان شاء الله ما راح نقصر معاك او غيرك\n\nدعواتنا لكم , ودعواتكم لنا الله يخليكم 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/159323/2", "user": "user9645", "ts": 1396526880000, "tid": 159323, "pn": 2}}', 1396526880000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1358269-ee398', 'stk-user7614', 'EE 398', 'info', '{"desc": "إضافة وتعليق\n\nهلا عبدالرحمن … معك عمر\n\nأنا طلعت الترم هذا للكواب … تبي الصدق بهذلوني الجامعة … (الله يصلحهم) … لو إني مصحصح أخذت كوأب سنع في شركة سنعة … الحمد الله على كل حال …\n\nأنا رحت للكهرباء بعد ملاحق طويل … أغلبهم كان ردهم “تأخرت علينا” منهم المتقدمة .\n\nبس تبي الصدق مرة مرتاح ومكروف في نفس الوقت … 🤪\n\nمرتاح دواما ومكروف شغلا …\n\nأبوداحم لو بغيت هندسة ابعد عن الشركات البرمجية … علم و أغلب اللي كلمتهم يبغوني أبرمج وأنا معقول في السالفة ما نيب طلقة زي بعض أخويانا … 🥰\n\nدور شركات شبكات أو اختار شبكات …\n\nأنا جتني مايكروسوفت وسيسكو و ثالس …\n\nكنت أبغى سيسكو بس بهذلوني ومايكروسوفت كانوا يبغون (Salesman) دعائي وقابلوني وكل شي وفي النهاية مهب مرة …\n\nثالس نفس الفكرة … بس في احتمال يدخلونك شبكات … احرص عليها لو قدرت …\n\nبالنسبة للريبورت سو على الأقل ثلاث مشاريع … رن عليهم لين يعطونك …\n\nاسأل خياري عنها يبين لك السالفة …\n\nهذا اللي عندي الحين … اسأل وأرد .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/158201/10", "user": "user7614", "ts": 1398610071000, "tid": 158201, "pn": 10}}', 1398610071000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p416777-ee398', 'stk-patriot', 'EE 398', 'info', '{"desc": "طلاب الميكانيكال ياخدو الكوأب في شركات كثيرة منها أرامكو و سابك و شركة الكهربا و GE و الخطوط و JGC اليابانية في اليابان و الفلبين.\nأما بالنسبة لقريدات الEvaluation حقت الشركة فهي أفضل في الشركات السعودية كأرامكو و سابك و الخطوط. أما بالنسبة للشباب اللي راحو شركة زي JGC في اليابان فكانت شديدة عليهم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/74280/3", "user": "patriot", "ts": 1245506053000, "tid": 74280, "pn": 3}}', 1245506053000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1444522-ee398', 'stk-ahmed_alhntoshi', 'EE 398', 'info', '{"desc": "نوع التدريب/ COOP\nاسم الشركة أو جهة التدريب :\nالشركة العربية لصناعة الورق ( طبعا هم يعيدوا تدوير الورق )\n\nالسنة : 2013- اترام 123 131\nالتخصص + الجامعة: AEE الكليات الجامعية التابعة للبترول - كلية الهندسة\n\nمكان التدريب + القسم :\nالدمام الصناعية 2 - القسم الكهربائي\nالمكافأة : 1500\nطريقة التقديم : يدوي بعد ما استفسرنا منهم بيوم المهنة 122 بالحفر\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة,… ) :\n\nالشركة كمهندس كهربائي حلوة, تقريبا كل الاجهزة متوفرة من محولات ومولدات وقواطع ومئات المحركات وبشكل دوري يصير فيه هبوط للنظام فتستيفد كيف تجد الخلل ، وفيه ورشة لتفكيك المحركات \" موتورز \" تنبش ام هيكل الموتور\nبس عيبها اني انزل مع المهندس ابفهم المشكلة كل كلامهم هندي\nوالقسم جنسيته كلهم هندية عن بكرة ابيهم فيه عنصرية وشوية هياط اثناء الكلام ومافي مرونة مع المتدرب \" قبل لا يلبي طلبك يفكر كيف يصرفك \"\n\nماعطوني مكتب ولا حتى كبينة بوقت الفراغ اشتغل ع الريبورت ، ابد تقول طير اوقف هنا وهناك\n\nكل ماتصير مشكلة اقط وجهي معهم بس ما استفيد لا يتكلمون عربي ولا انقليزي رغم اني طلبت منهم يتكلموا بالانقليزي بس تنطيش\n\nلقيت عامل حساوي واثناء الدردشة يقول انا ماواجهت مشكلة مثلك تعلمت لغتهم وهاذا انا ارطل معهم !؟ يعمي فاضيلك انا اتعلم لغتهم هههههههه\n\nتقريبا استفدت من مكاتب الارشيف كان فيها ملفات عن الاجهزة ومصدر المعلومات وهو مركز التحميل ل ABB وسالت الفني عن مشكلتين صارت فبديت ابحث عن Cpacitor fuses , Motors Starters\nومشيت حالي بكيس ستدي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/29", "user": "Ahmed_Alhntoshi", "ts": 1458530801000, "tid": 170460, "pn": 29}}', 1458530801000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p518708-ee398', 'stk-x_zero', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nالحمدلله على كل حال\nما لقيت شركة بالخارج اخذ فيها كوأب عشان اخذ خبرة بتخصص الكهرباء 😦\n\nوكل الشركات المعروفة والقوية بالسعودية اخوياي مطبقين فيها يقولون شغلهم اي كلام واصلا يشوفونك عالة عليهم واللي طفشان بالعمل ويتصفح بريده والثاني ما يحضر الا متاخر وبالاخير ما ياخذوا خبرة ولا يستفيدوا\n\nابي شركة ما تهتم بالحضور والغياب وممكن اسوي فيها شغل بسيط عشان اكتبها بالتقرير !\nيعني وش الفايدة احضر واجلس على النت ولا بالمكتب؟\n\nبس لو فيه شركة تعطي خبرة يا ليت تدلوني عليها\nاذا ما فيه دلوني على شركة ما تهتم بالحضور !\n\nوشكرا…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/81930/1", "user": "X_zErO", "ts": 1262895280000, "tid": 81930, "pn": 1}}', 1262895280000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1234001-ee398', 'stk-_2611', 'EE 398', 'info', '{"desc": "انا تدربت ع بعد 70 كم من البيت ولا عطونى بدل بعد …\n\nوالراتب 2000 ريال لانى كواب …\n\nالصيفى اخر الفتره يعطونك 4000 يمكن\n\nبصراحه ماداومت اكثر من 15 يوم من اصل 7 شهور\n\nاصل الدجه هالشركه وكل ماجيت تستفيد صرفوك …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/145952/5", "user": "_2611", "ts": 1370898741000, "tid": 145952, "pn": 5}}', 1370898741000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1234271-ee398', 'stk-_11115', 'EE 398', 'info', '{"desc": "أخ “مزاجي26” ما أوافقك أبداً أنا كوأب في الشركة …\n\nبالعكس شركة الكهرباء أفضل بيئة تدريبية لمهندسي الكهرب خصوصاً …\n\nالدوام أغلبه في الفيلد (محطات توزيع وخطوط نقل وتوليد … إلخ) من 7 الصباح إلى 3 المساء وموظفيها متعاونين مع المتدربين ويهتمون فيهم بشكل غير طبيعي …\n\nبصراحة سواءاً المهندس أو الفني يفهمك ويشرح لك و يعطيك كل اللي عنده وبكل اللي يقدر عليه وبصراحة فيها مهندسين خبراتهم تضاهي الدكاتره …\n\nهذا من واقع تجربة والحق ينقال وأنا أنصح اللي بيأخذ كوأب ويبي يكتسب خبرة و يطور نفسه في تخصصه ، شركة الكهرباء أفضل خيار لأن أغلب الشركات الثانية تكرفك عالفاضي …\n\nدمت بود …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/145952/7", "user": "_11115", "ts": 1370992596000, "tid": 145952, "pn": 7}}', 1370992596000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1034467-ee398', 'stk-al-hashim', 'EE 398', 'info', '{"desc": "السلام عليكم ورحمه الله وبركاته\n\nتعلن شركة الكاتيل لوسنت عن فرص للتدريب التعاوني وذلك في مدينة الرياض للتخصصات التالية:\n\nالهندسة الصناعيه والنظم … عدد 2\nالهندسة الكهربائيه (اتصالات) … عدد 12\nنظم المعلومات الادارية … عدد 2\nهندسة الحاسب الآلي … عدد 1\n\nالشركة لها مشاريع كثيره مع مشغلي الخدمات بالمملكة مثل الاتصالات السعوديه وموبايلي وزين وكذلك بعض الشركات العملاقه مثل ارامكو السعودية\n\nللتواصل:\nيرجى ارسال السيرة الذاتيه على البريد التالي\nIbrahim.olayan@alcatel\\-lucent.com\nالسيد ابراهيم العليان - الرياض\nالهاتف: 012839080\n\nعلى ان يكون عنوان الرساله: تدريب تعاوني – جامعة الملك فهد للبترول والمعادن\n\nبالتوفيق يا شباب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-training-with-alcatel-lucent-2012/125322/1", "user": "AL-HASHIM", "ts": 1336484139000, "tid": 125322, "pn": 1}}', 1336484139000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1444205-ee398', 'stk-ibra1991', 'EE 398', 'info', '{"desc": "نوع التدريب Summer\n\nاسم الشركة أو جهة التدريب : شركة الكهرب\n\nالسنة : 2014\nالتخصص : EE\nمكان التدريب : القطاع الشرقي (الشمالية)\nالمكافأة : 0\nطريقة التقديم : ادارة الشركة\n\nإضافات : تعلمت شي جديد لكن ماكانت الشركة مهيئة لتدريب وكان الوضع ما أحد يسال عنك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/28", "user": "ibra1991", "ts": 1458043604000, "tid": 170460, "pn": 28}}', 1458043604000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1478030-ee398', 'stk-k_94', 'EE 398', 'info', '{"desc": "نوع التدريب ( Coop )\n\nاسم الشركة : شلمبرجير\n\nالسنة : 2017 ( 162+163)\n\nالتخصص + الجامعة: CHE ; KFUPM\n\nمكان التدريب + القسم : القسم Drilling and measurement , بالنسبة لمكان التدريب اماكن مختلفه يعتمد على موقع الحفر ( تناجيب , الخرسانية , العثمانية , ابو جفان , المزاليج , خريص , الخ … )\n\nالمكافأة : 1500 ريال\n\nطريقة التقديم : يوم التدريب بالجامعة\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة, الكورسات الي يمكن تفيدك في التدريب… ) : الشركة حلوة للي يعطيها لكن شخصيا ما ناسبتني , دوام 7 ايام بالاسبوع 12 ساعه باليوم والاجازات بالقطاره لانك طالب كواب , لكن ما قصر مديري جمع اجازاتي واعطاني اياها اخر التدريب 🤠 , لكن كل التعب والقروشة ذي ما تسوى ال1500 وطبعا القسم ما فيه شي كمكل ولا اعتقد اي تخصص ندرسه بالجامعه مشابه له ( ممكن حقين الكهرب في لهم signal والميكانيكل ممكن يدبرون لهم شي بالادوات ) اصلا مسماك Field engineer يعني يعتبر شي مغاير تماما للجامعه وللامانه الشغله ما يبي لها هندسة ولا شي , حتى الشباب من كلية الجبيل وينبع الصناعية يسوون نفس الشغل الفرق بينكم يكون في المسمى الوظيفي فقط .\n\nالشركة تضغط عليك بالتدريب ( يعتمد عالقسم طبعا ) ولكن ذا الشي يخليك تتعلم بسرعه , المشكلة الوحيده انها مو بتخصصك يعني ممكن تاكلها بالفاينل ريبورت X_X , شخصيا جتني شركتين غيرها في قلب تخصصي ولكن فضلت اختار شلمبرجير عشان اشوف تناسبني اختارها بعد التخرج او لا ولله الحمد 7 شهور افادتني كثييير عن الشركة والمستقبل الوظيفي ونظام الترقيات والكورسات حقت التطوير وشخصيا اشوف اي طالب يطبق بشركة حاول تحتك بالموظفين كثير عشان تعرف عن الشركة اكثر لانه مستحيل كل المعلومات تلاقيها بالنت , لازم تسمع من ناس لهم سنتين او ثلاث بالشركة …\n\nالصراحه ماني من الناس اللي اعرف اشرح تجربتي بالشكل المناسب لكن اللي عنده اسئلة مستعد اجاوبها سواء عن التدريب او القسم بشكل عام 🙄", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/64", "user": "K_94", "ts": 1501843965000, "tid": 170460, "pn": 64}}', 1501843965000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1511896-ee398', 'stk-homoud295', 'EE 398', 'info', '{"desc": "اسم الشركة أو جهة التدريب: ارامكو السعودية\nنوع التدريب : COOP\nالسنة : 2019\nالتخصص + الجامعة:\nME - Jubail University College\nمكان التدريب + القسم :\nمصفاة راس تنورة - صيانة معامل التكرير الشمالية\nالمكافأة : 4500 ريال\nطريقة التقديم : الموقع الرسمي\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة, الكورسات الي يمكن تفيدك في التدريب… ) :\n\nبسم الله الرحمن الرحيم ، أتمنى تفيدكم تجربتي للتدريب التعاوني مع شركة أرامكو السعودية.\n\nبفصّل الموضوع على شكل اسئلة واجوبة:\n\n١- هل يوجد خطة للمتدرب ، وهل طبقتها ؟\n\nنعم ، يوجد خطة بمسمى (Individual Development Plan) أو IDP يعطونها للمتدرب وللموظف الجديد فيها نقاط بالمسؤوليات والمهام الخاصة ، والحمدلله قدرت اطبقها بكل يسر بالتعاون مع الرئيس المباشر. وهنا اذكر المسؤوليات بالخطة للفائدة:\n\n• Understand the maintenance planning & scheduling process.\n\n• Gain basic understanding of compnay contracting procedure.\n\n• Work with mechanical unit for hands on experience on rotating/static equipment.\n\n• Work with electrical and instrumentation unit for hands on experience.\n\n• Worked with plnt maintenance engineer for exposure to company international standards as well as engineering drawings.\n\n• Work with maintenance engineer to gain the understanding of work order planning, material ordering and execution.\n\n٢- أهم المهارات المكتسبة؟\n\n- حضور الاجتماعات والمشاركة فيها من أهم الامور اللي حبيت ان اطور نفسي فيها ، فكنت احضر اجتماعين على الاقل باليوم بالبلانت وبالقسم والمشاركة في التحديات اللي تواجهنا كل يوم.\n\n- مهارات التواصل بشكل عام والاندماج في بيئة العمل يجعل منك شخص ناجح بكل المقاييس.\n\n- الأمن والسلامة وهنا فعلاً اقدر اقول ان أرامكو تشكر على جهودها في هذا المجال ، و غيرت فيني الشي الكثير سواء داخل العمل او حتى على اسلوب قيادتي للسيارة.\n\n- التعرف على العالم الهندسي الواقعي ، كلنا ملينا من قراءة الكتب والسلايدات لكن لما تنزل المصنع او البلانت وتشوف بعينك اللي درسته وتكون قادر على الربط مابين النظريات والشيء الواقعي فعلا شي يخليك ماتندم لحظة وحدة على دراستك.\n\n- الكورساااات تبع ارامكو Elearning ، اخذت مايقارب ٢٠ كورس مختلفة مابين السلامة واخلاقيات المهنة والهندسة ومعامل التكرير و الكثير. للأمانة انصح كل متدرب بأرامكو يستفيد من هذا الشي الجميل صراحة.\n\n٣- كيف كانت بيئة العمل ؟\n\n- اجابة صادقة ، بيئة ودودة جدا وواجهت ناس كثير تحب الخير ومساعدة الطلاب المتدربين والاهم من ذا ان الموظفين يحبون اللي جالسين يسوونه.\n\n٤- وش التحديات اللي واجهتها ؟\n\n- السوبرفايزر وكلني مهمة وهي اني كمهندس صيانة مثل الزملاء الموظفين اغطي معملين تكرير من اكبر المعامل بالمصفاة الشمالية والمسؤولة عن انتاج البنزين ٩١ و ٩٥ ، طبعا المهمة لمدة اسبوع وكنت احضر الاجتماعات يوميا بالمعامل مع الاوبريشن واسجل اعمال الصيانة المطلوبة وايضا نناقش المشاكل المتواجدة وكيفية حلها وطبعا زيارة اعمال الصيانة بالمعمل يوميا والتأكد من انجازها بالشكل المطلوب.\n\n- تم تعييني في اخر شهر بالتدريب في اعمال شت داون لبلانت معين ، طبعا مسماها (Turnaround & Inspection) او T&I Activities ، وهي ايقاف تشغيل المعمل بشكل جزئي او كلياً لإتمام اعمال الصيانة للمعدات المهمة مثلا الهيت اكسشينجر … الرياكتر … البويلر والفرنس … البمب والكمبرسر وغيرها الكثير. تجربة كانت فريدة من نوعها وهي الاهم للمهندس الميكانيكي بالذات لانك تشوف جميع المعدات والآلات مفتوحة ويتم صيانتها وهنا تكمن الفائدة انك تعرف القطع الداخلية والخارجية.\n\n٥- كمهندس ميكانيكي وش الكورسات اللي استفدت منها؟\n\n- اكثر مادة استفدت منها شخصيا هي مادة الكتڤ Maintenance Engineering … فعلا كل شي درسته شفته وطبقته وانصح اي مهندس ميكانيكي ياخذ المادة ضرورية جدا ، اغلب المهندسين الميكانيكيين هناك بمسمى maintenance engineer.\n\n- Heat Transfer ( عشان الهيت اكسشينجر اكثر شي ).\n\n- Fluid Mechanics (pumps, compressors, turbines, pipes)\n\n٦- كيف كانت تجربتك؟ (عطنا الزبدة)\n\nولله الحمد اولاً واخراً التجربة كانت ممتازة جدا والتوفيق من الله سبحانه ، واتمنى لكم التوفيق جميعاً لازم تعرفون ارامكو بحر بأقسامها وتخصصاتها لكن الكلام اللي ملحه فيه ان مصفاة راس تنورة يسمونها مدرسة ارامكو ، لان اولا اكبر مصفاة بالشرق الاوسط قبل جيزان حالياً وفيها اكثر من معمل تكرير وبالتالي المهندسين بيستفيدون جدا من اللي بيشوفونه ويتعلمونه ، ثانياً اغلبهم خبرات تفوق ال٢٠ سنه يعني ماشاء الله كيف ماتبي تستفيد.\n\nهذا اللي كان عندي واتمنى تعذروني طولت بالموضوع لكن حبيت افيد الكل باللي اقدر واشارك تجربتي ، واللي عنده سؤال انا حاضر … دعواتكم واتمنى لكم التوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/81", "user": "homoud295", "ts": 1562107377000, "tid": 170460, "pn": 81}}', 1562107377000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1043656-ee398', 'stk-shaheen', 'EE 398', 'info', '{"desc": "شباب شركة مزون للاتصالات طالبين طلاب كووب الان (طلاب كهرب بس ) 👍\n\nالعدد غير محدد ارسلو ال CV على الايميل aalrafaa@gmail.com\n\nاي استسفارات اتصلوا على الرقم 0500343141\n\nويعطون رواتب حلوة و التطبيق في الرياض 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/126199/1", "user": "shaheen", "ts": 1337866274000, "tid": 126199, "pn": 1}}', 1337866274000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1439983-ee398', 'stk-big_h', 'EE 398', 'info', '{"desc": "السلام عليكم , أحب انقل لكم تجربتي في التدريب مع هذه الشركة , خصوصا بعد إعلانهم اليوم , ولقرب توقيت البحث عن فرص التدريب\nأكثر من يفيده الموضوع متخصص الهندسة الكهربائية .\n\nالشركة تنقسم ل 3 أقسام رئيسية : التوليد , النقل , التوزيع .\nفالبداية توقعت اني راح امر على كل هذه الأقسام , اكتشفت ان هذه الأقسام منفصلة عن بعض بإدارات ومباني مختلفة , تقدر تعتبرها 3 شركات مختلفة لكن تعمل تحت غطاء واحد . بمعنى المبنى اللي تشوفه لشركة الكهرباء مو شرط فيه كل الأقسام .\nتدريبي كان في قسم التوزيع في منطقة المدينة المنورة , اخترت المنطقة لاني قدمت وارسلت اوراقي لفرع المدينة , لكن ما اخترت القسم ,اغلب تخصصات الكهرباء يكونوا بالتوزيع تلقائيا , لأن مثل ما قلت الأقسام الباقية لها ادارات مختلفة وتحتاج تصريح دخول لتجاوز الامن الصناعي وغيرها .\n\nفالبداية رحت لشؤون الموظفين اعطيتهم خطاب التدريب , طلبوا مني رقم حسابي مع الايبان مطبوع في ورقة حتى يعطوني المكافأة , بعدها حولوني على اول قسم للتدريب لي . بالمناسبة المكافأة ما تاخذها الا نهاية تدريبك دفعة واحدة مو شهريا .\nالتوزيع ينقسم ل 4 أقسام هي : التخطيط - الانشاءات - الصيانة - العمليات , كل قسم له فروع تحتها .\nبداية تدريبي كان فالعمليات .\nشؤون الموظفين يتوقعوا انك تداوم في مكان واحد لمدة 7 شهور , لكن هذا سيء لك ولكتابة الريبورت , كلمت سكرتير اول قسم تدربت فيه اللي هو العمليات لانه هو اللي جاته رسالة اني متدرب فالشركة , سوالي جدول لكل الاقسام من عنده وطبعلي هو , قالي اي قسم روح وريهم هذا الجدول وبيقبولك كمتدرب , ولو ما قبلو كلمني أرسل رسالة تدريبك للقسم اللي تبغا تروحله , وسويت مثل ما قال وزبط الموضوع وقدرت امر على كل اقسام التوزيع , مو شرط تسوي مثل طريقتي لكن انصحك ما تجلس بمكان واحد .\n\nبدأت الدوام , اول عيب راح تلاحظه وهذا شيء في اغلب الشركات مو بس الكهرباء , وهو انه ما في قسم مخصص لتدريبك ومافي موظف مخصص في كل قسم يدربك , لازم تستلبش وتكلمهم عشان تاخذ المعلومات , لكن موظفي الكهرباء كانوا متعاونين جدا , بس ملاحظة مهمة وهي انه لا تستحي تتكلم لانه محد بيعطيك وجه لو سكتت\n\nبالنسبة للدوام , كل الأقسام تقريبا نصف شغلها مكتبي والنص ميداني , تلاقي فريق مهندسين بالمكتب وفريق ميداني من التقنين , ميزة هذه الشركة هي انه كل يوم في عمل ميداني , الساعة 7:30 الصباح كل يوم يخرجو التقنين , ركز على كلمة كل يوم , نصيحة لا تجلس فالمكتب كثير , ممكن اول يوم او يومين اجلس مع المهندس يفهمك شوي عن عملهم , بس الأفضل انزل دائما مع التقنين للميدان , كل يوم ممكن تشوف شي جديد وبالتالي تقدر تكتب أشياء كثير في الريبورت .\n\nوقت الدوام كان مريح جدا ومن أفضل الأشياء في الشركة . كنت اول يوم او يومين فالقسم اكون فالمكتب عشان افهم فكرة القسم وكنت اتفاهم مع المهندس مع مين حيطلعني من التقنيين واخذ رقم اللي حاطلع معاه واخلص بدري واروح البيت, الايام الباقية اطلع ميدان , من 7:30 اخلص 12 الظهر وارجع البيت . طبعا يعتمد على الشغل الميداني ويعتمد على رغبتك , يعني مرات كنت احضر مرة وحدة مع التقني فالميدان ويقولي الباقي زيها لو تبغا تجلس حياك لو ما تبغا عادي امشي .\n\nانا بدات الشركة بترتيب خاطيء في تسلسل عملية التوزيع , بدأت بالعمليات - صيانة - انشاءات - تخطيط , والترتيب الصح هو العكس تماما , يعني العمليات هي اخر خطوة . فالنهاية الموضوع ما فرق معاي يعني فهمت كل شيء وما تلخبطت كثير , بس ممكن أفضل لو تبدأ بالترتيب الصح .\n\nبالنسبة للحضور , فما وقعت ولا على دفتر تحضير لأي قسم رحتله , فالنهاية لما خلصت التدريب رجعت لسكرتير القسم اللي كلمته فالبداية وسوالي الجدول, وقلتله اني خلصت لفلفة وتدريب , ارسل رسالة لشؤون الموظفين اني ملتزم وخلصت تدريبي وقبلوها مني , قسم الموظفين يحسبني في مكان واحد وما يدروا شي , الوضع سهالات يعني .\n\nحاولت أغطي أغلب الجوانب اللي يحتاجها المتدرب فالشركة, لو في أي سؤال أنا حاضر , وان شالله تشوفو اللي كتبته مفيد لكم .\nبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/171850/1", "user": "Big_H", "ts": 1453315061000, "tid": 171850, "pn": 1}}', 1453315061000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p394577-ee398', 'stk-only_xeer', 'EE 398', 'info', '{"desc": "good day\n\nI am an electrical engineering Co-op student in Saudi Aramco\n\nI want to know how to write the co-op report\n\nand if you have some examples that will be fine", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/the-coop-report-for-electrical-engineering/72622/1", "user": "only_XeeR", "ts": 1240129114000, "tid": 72622, "pn": 1}}', 1240129114000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1010104-ee398', 'stk-user8401', 'EE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nتخصصي هندسه كهربائيه و عندي كوأب الترم هذا وخلصت اول Progress report بس في شي ماني فاهم وش قصده فيه\n\nاللي هو الـ case studies طبعا سألت الكوأب ادفايزر وما فادني في اي شي\n\nلا هنتوا يا شباب …اللي عنده خلفيه عن الموضوع يعلمني واكون له من الشاكرين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/progress-report/123122/1", "user": "user8401", "ts": 1331975526000, "tid": 123122, "pn": 1}}', 1331975526000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p415019-ee398', 'stk-bo-salem', 'EE 398', 'info', '{"desc": "مرحبا حسين،\n\nبالنسبة للكواب أدفايزر فهو الأندلسي،،\nوعلى فكرة أنا طبقت في شلمبرقير، وكان شغلهم كله اناليسز للداتا الطالعة من الويل(كهرب) وكانو كل اسبوعين يطالبوني بريبورت، وفي آخر شهر قالولي سو لنا بحث لتطوير التقنيات في التنقيب وسويت بحث مايقارب 40 صفحة!!\nيعني ماكنت أحتاج حتى أفكر أكتب شي ماسويته…\n\nبعد ماخلصت الكواب قالي رئيسي نبيك تشتغل معنا قلت له والمكان وين راح يكون؟؟ قالي نفس المكان الحالي يعني نفس الشغلة؟! طول الوقت في الفيلد معزول عن الأهل والناس،، ماوافقت.\n\nمعدلي أعلى من 3 بشوي…\nوقريد الكواب b!!!!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/74118/18", "user": "Bo-Salem", "ts": 1245191831000, "tid": 74118, "pn": 18}}', 1245191831000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p412188-ee398', 'stk-user3490', 'EE 398', 'info', '{"desc": "X_zErO\nأهلا ياخي\nانتبه يا خي من شلمبرجير أصلا هما ممكن ينسوك تخصصك\nكم واحد مهندس كهربائي قالي أنا مع شلمبرجير نسيت الكهرباء وصرت بتروليوم\nهذا غير انهم احيانا يودوك في الصحاري وكرف اسابيع متواصلة ما فيها اجازة يعني اهلك انساهم فترة العمل\n\nوالتدريب يا خي كثير من الشركات ما تعطي اهمية للتطبيق وبعض الرؤساء اصلا ما يدروا عنك\n\nوسيم عازب\n\nأهلا عزيزي\nيا خي القرش خليه لهم أنا أبغى أطلع من التدريب وعقلي ما زال معايا\nلأنو سبع شهور فاضي حيجيني اكتئاب نفسي\nأما بالنسبة لجو العمل فكلامك صحيح ومنطقي\nلكن أشوف انو موظف رسمي في الشركة أفضل من متدرب لأنو الأول يشوف اهتمام وراتب وورش عمل أما الثاني فهو في نعمة إذا حصل ايميل واحد من عندهم\n\nنمر\nأهلا فيك\nبالنسبة للمعدل ايوة بس المشكلة إذا جاب العيد يعني درجة سيئة في الكواب (سي أو سي بلس) ايش يسوي؟\nالترينيق أحسن حق اللي ما يبغى معدله ينزل لأنو ما عليه درجة\n\nHusain EE\nأهلا فيك\n\nما أختلف معاك وكلامك معقول\nومثل ما قلت لوسيم الفلوس خليها لهم وريحة الجامعة عندي احسن من الفلوس والفضاوة\nهذا اذا ما ودوك بعيد كمان عن اهلك عشان تصير الطامة أعظم فاضي ومنقطع اجتماعيا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/73870/7", "user": "user3490", "ts": 1244566866000, "tid": 73870, "pn": 7}}', 1244566866000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1534220-ee398', 'stk-abdullah_almaradi', 'EE 398', 'info', '{"desc": "السلام عليكم شباب\nايش رايكم ب التدريب التعاوني لدى شركة الكهرباء\n\nحاب استفسر عن شغله كمان للاشخاص الي قريب راحو للتدريب بشركة الكهرباء هل صحيح مافي مكافاة يعني معقوله اشتغل سبع شهور بدون شيء …\n\nاتمنى الي راح للتدريب التعاوني قريب يفيدني وشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/184571/1", "user": "Abdullah_almaradi", "ts": 1651843224000, "tid": 184571, "pn": 1}}', 1651843224000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1204208-ee398', 'stk-nayef', 'EE 398', 'info', '{"desc": "تعلن شركة تيناريس عن توفر فرص لبرنامج التدريب التعاوني (COOP) والمقرر بدءه خلال يونيو من العام 2013 لمدة 28 أسبوعاً\n\nحيث تقدم الشركة للمتقدمين السعوديين لهذا البرنامج فرصة الإحتكاك بأصحاب الخبرة في مجالها و التدريب المناسب في بيئة عمل مثالية يكون الإحتكاك فيها بموظفين ومدراء من جنسيات مختلفة حول العالم مما يضمن اكتساب الخبرة بالإضافة الى العوائد المادية المنافسة\n\nالتخصصات المطلوبة:\nالهندسة الميكانيكية\nالهندسة الكهربائية\nالهندسة الصناعية\nالهندسة الكيميائية\n\nالرجاء إرسال السيرة الذاتية إلى البريد الإلكتروني المذكور أدناه خلال مدة لا تتجاوز April 12,2013\n\nPlease submit your CVs to:\nmshakeel@tenaris.com\n\nلمعلومات حول الشركة:\nwww.tenaris.com\n038127701", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-tenaris/142533/1", "user": "NaYeF", "ts": 1364822649000, "tid": 142533, "pn": 1}}', 1364822649000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1178369-ee398', 'stk-aboody_53', 'EE 398', 'info', '{"desc": "مشكور يا EE-220 كفيت ووفيت بس أنت أخذت الموضوع من مصلحة الطالب بس لو أخذنا كيف الشركات تختار\nهل تفضل fresh graduate آخذ سمر أو كوأب و هذي مسألة مهمة ننتظر اقتراحات الباقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-summer-training/140003/4", "user": "Aboody_53", "ts": 1360246926000, "tid": 140003, "pn": 4}}', 1360246926000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1021430-ee398', 'stk-user6200', 'EE 398', 'info', '{"desc": "والله كلامك اللي غير منطقي بصراحة\n\nاولا انا سويت ثلاث مقابلات مع ارامكو وسالوني وش المواد الاختيارية اللي اخذتها وراح اخذها\n\nوايضا سالوني بالتفاصيل اللي فيها وليه اخترتها ولم يسالوني عن مواد التخصص الاساسية\n\nوبالعكس المواد الاختيارية وانا اخذها الان هي اللي تحس فيها الحس الهندسي والتصميم وتحس كانك مهندس لانك تعديت مرحلة الاساسيات الى تصميم اجهزة وتطويرها وراح تفيدني كثييير\n\nبعد التخرج من حيث المعلومات اللي عندي\n\nاساسيات + مواد اختيارية + سمر ترينيق\n\nاساسيات + كواب\n\nايهم افضل بعد ماتستلم وظيفتك الاول طبعا اضافتك لك شي كثيررر\n\nواحد زملائي دفعتي كان ابلايد ولما قبلوه ارامكو ccp يعني ابتعاث داخلي (كتوظيف قبل التخرج) قالوا له حول الى ساينس مع انه متفوق ما شاء الله عليه وفعلا حول وتاخر لان كان عامل حسابه انه كواب لكن لما سالته ليه منزل مواد اختيارية قال هم اجبروني احول ساينس ولازم اخذ سمر ترينيق\n\nواعرفه معرفه شخصية لو تبي اسمه عادي 🤠\n\nوايضا عمي مهندس كهربائي يقول راتبه اقل من زملائه الساينس حقطوا له الشركة لان اسم الجامعة فيها تطبيقية طبعا هو في شركة الكهرباء\n\nجامعة العلوم التطبيقية بالاردن\n\nونصحني ادخل ساينس بقوووة من كل النواحي\n\nوكل ما اسال الموظفين بالشركات يقولون علوم هندسة\n\nلكن هنا المجتمع الطلابي يقولون مايفرق مايفرق ارفع درجاتك بالكواب\n\nعموما انا اقول كلامي عن تجربة وتجارب واقعية\n\nلكن لما اصادف اي احد ينصح بالتطبيقية الا البعض يقول خبرة او يقول ممكن تاخذك الشركة اللي تطبق فيها\n\nعلما ان اقل من سنتين ليست خبرة ولا تقيس الخبرة فترة 6 شهور وايضا حتى السمر ترييننق ممكن تاخذك الشركة اللي تطبق فيها ما المانع\n\nانت قلت تهتم بالتطبيق\n\nطيب الخريج الجديد تعتبره الشركات ليس لديه اي خبرة سواء كان كواب او سمر تريننيق\n\nوالتفضيل يكون (بالمعدل والعلم)\n\nعموما بالتوفيق لكم ولكم حرية الاختيار\n\nوهذا رايي و وجهة نظري\n\nالموضوع ليس نقاش كل واحد يقول وجهة نظرهـ والناس تختار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/124139/7", "user": "user6200", "ts": 1334266043000, "tid": 124139, "pn": 7}}', 1334266043000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1021484-ee398', 'stk-abu_3zzoz', 'EE 398', 'info', '{"desc": "وايضا عمي مهندس كهربائي يقول راتبه اقل من زملائه الساينس حقطوا له الشركة لان اسم الجامعة فيها تطبيقية طبعا هو في شركة الكهرباء\n\nاذا تقصد راتب الابلايد يفرق عن الساينس\nفاللي خلقني وخلقك مو راضية تخش مخي ولا راح تخش\n+\nانت الوحيد من عرفت الجامعة اللي يقول الساينس أفضل من الابلايد في المنتدى وخارج المنتدى 🙂\n🌹\n\nبالنسبة لصاحب الموضوع\nهي مجرد فروقات بسيطة جدا , مع أني أشوف ان الكفة لصالح الكوأب اذا انت ناوي تتوظف ع طول\n- 50 % من اللي أعرفهم وقعوا عقود مع الشركات اللي طبقوا فيها مثل شلمبرجير و أرامكو ( ممكن اقدر احكم على أداءك في 28 أسبوع بينما من وجهة نظري صعبة أحكم عليك من خلال أقل من شهرين )\n\nعيب الكوأب انه ممكن يجبرك تتأخر سمستر وهذا اللي صار مع أكثر اللي أعرفهم\nلانه ترم + صيف = 9 ساعات فقط ( تقدر تخلص اكثر من 20 ساعة اذا انت في الجامعه )\n\nفي الأخير الارزاق بيد الله\nوشهادتك مجرد طريق الى المقابلة الشخصية لا غير اللي ممكن تكون طريقك الى الوظيفة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/124139/8", "user": "Abu_3zzoz", "ts": 1334273150000, "tid": 124139, "pn": 8}}', 1334273150000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p625675-ee398', 'stk-rharbi', 'EE 398', 'info', '{"desc": "🌹السلام عليكم 🌹\n\nتعلن الشركة السعوديه للخطوط الحديده (سار) عن توفر فرص تدريب لطلاب التدريب التعاوني(COOP) لتخصص الهندسه الكهربائيه بالمميزات التاليه:\n\nمكافئه تدريب بمقدار 3000 ريال شهريا\nتوفير السكن\nتوفير وسيله مواصلات للعمل\nعلما بأن التعيين سيكون بالمواقع التاليه (حائل,الجوف,حفر الباطن).وأحب أن أنوه إخواني الطلاب أنني أحد حديثي التخرج من جامعة البترول وقد إلتحقت بهذا المشروع قبل عشرة أشهر واكد لكم أن الخبره الميدانيه اللتي حصلت عليها حتى الان تفوق زملائي الخريجين في الشركات الكبرى.حيث أنني الأن مشرف على تركيب وتشغيل ثلاثة عشر نظامآ من انظمة الإتصال والتحكم ,مثال(GSM ,SDH, optical fiber) وغيرها من أحدث أنظمة الأتصالات والتحكم بالقطارات في العالم.\n\nوحيث ان المملكه مقبله على عدد كبير من مشاريع القطارا ت كقطار الحرمين,مشروع المشاعر,الجسر البري وغيرها من المشاريع فأني أكد لكم انها فرصة ذهبيه لو عاد بيه الزمن لألتحقت بالمشروع كمتدرب قبل أن اتوظف.\n\nفعلا جميع الراغبين إرسال السيره الذاتيه للإيميل التالي مع جعل موضوع الرساله (S&T COOP):\n\ncareer@sar.com.sa\n\nوالله ولي التوفيق\n\nريان عبدالله الحربي\nالمهندس المشرف لنظام الإشارت والتحكم بحائل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/89583/1", "user": "Rharbi", "ts": 1276030345000, "tid": 89583, "pn": 1}}', 1276030345000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p628468-ee398', 'stk-no_chance', 'EE 398', 'info', '{"desc": "ما أخاف إلا فرصة ذهبية\nالشركات الأخرى تعطي 5000 ريال وأنتو تعطو 3000", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/89583/6", "user": "No_Chance", "ts": 1276272497000, "tid": 89583, "pn": 6}}', 1276272497000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p628471-ee398', 'stk-user1655', 'EE 398', 'info', '{"desc": "^^\nأرامكو تعطي 3000 ريال وسابك 2500 وشلمبرجير 3000\nشركة أو شركتين بس يعطون 5000 ريال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/89583/7", "user": "user1655", "ts": 1276272662000, "tid": 89583, "pn": 7}}', 1276272662000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1056564-ee398', 'stk-user2781', 'EE 398', 'info', '{"desc": "هلا بك اخوي\n\nانا طبقت كوآب في احد شركات سابك 🙂\n\n\\\n\nالتطوير والدورات كلها تعتمد ع مديرك بالادارة\nبس اخبر شركة كيميا كريمه مع موظفيها بما ان شركهم امريكي 🌹\n\n(الي يقدر يجاوب هذا السؤال هم موظفوا كيميا )\n\n\\\n\nإذا اشتغلت مهندس كهربائي في ادارة الصيانه او الاعتماديه (reliability )\nبتكون ممتاز في الـ distribution والبروتيكشن والماشين\nوطبعاً بتفهم ال sub station\n\nوبكذا تقدر تروح اي شركه ثانيه نفس البيزنيس\nمثل ارامكو او شيفرون او what ever\n\n\\\n\nنظام تمليك المنازل يعتمد ع قريدك وخدمتك وعلى عدد عيالك وزحمه 🤠\nبس انت كمهندس تبدأ بقريد 10 ما شاء الله، ما اتوقع تتاخر\n\n\\\n\nايه اكيد الباب مفتوح للكهربائي والميكانيكي\nوانت كثر ما تطلع فوق لازم تقوي نفسك بالـ management skills\nيوم كنت اطبق قريت الـ job description حق الـ superintended لقسمنا\nوكان من المطلوب انه يفضل انه يكون كهربائي او ميكانيكي …\n\n\\\n\nعفواً عزيزي\nومعليش ما قدرت اجاوبك لاني كنت كواب 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/127455/7", "user": "user2781", "ts": 1339927418000, "tid": 127455, "pn": 7}}', 1339927418000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1417057-ee398', 'stk-maslamh', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nيوجد فرص تدريب تعاوني Co-op في تحالف BACS مشروع مترو الرياض لاين 1&2 لتخصصات الهندسة المدنية, الميكانيكية, الكهربائية, المعمارية. شركات التحالف بكتل,المباني, اتحاد المقاولين.\nالعمل مشترك بين جميع الشركات يعني التيم تحصل فيه موظفين من جميع الشركات الثلاث.\n\nالي له رغبه يرسل الCV (يكون المعدل في الCV) على الايميل هذا:\n\namalgaht@bacsrmp.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/167850/1", "user": "Maslamh", "ts": 1417499640000, "tid": 167850, "pn": 1}}', 1417499640000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1507731-ee398', 'stk-abdullahf97', 'EE 398', 'info', '{"desc": "السلام عليكم عندي مقابلة مع شركة Rexam United Arab Can Manufacturing Company فرصة تدريب تعاوني.\n\nتخصصي هندسة كهربائية، الفرصة جاتني عن طريق الجامعة.\n\nو حاب استفسر عن الشركة بصفة عامة و كيف الشغل فيها.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rexam-united-arab-can-manufacturing-company-ruac/181221/1", "user": "Abdullahf97", "ts": 1553450883000, "tid": 181221, "pn": 1}}', 1553450883000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1483606-ee398', 'stk-jehibaru', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nانا طالب في كلية ينبع الصناعية واخرترم ان شاء الله في الدبلوم وناوي اكمل بكالوريوس ان شاء الله تخصص هندسة كهربائية\n\nانا حاب استفسر او اعرف عن الشركات اللي اقدر اطبق فيها في الشرقية وسمعتها حلوة من ناحية التطبيق فيها\nواللي يعطو رواتب عشان اقدر استأجر فيها شقة\n\nي ريت تقولولي ايش الشركات اللي:\n1- تنصحو اني اطبق فيها في الترم الثاني\n2- ويعطونا رواتب\n3- وهل يعطونا سكن\nويا ريت تعطوني رابط التقديم\n\nانا سمعت عن schneider electric\nGE\nJohnson control\nsaudi cement\nRosen\nهذي ال 5 اللي عرفتها عن طريق المنتدى وما اعرف كيف اقدم عليها هل في رابط في موقع كل شركة او ايش .\nاول 3 شركات لها مباني في جدة ف راح احاول اقدم عندها واقلهم اني بطبق في الشرقية\nوالباقية احاول اتواصل معاهم عن طريق الايميل او اي طريقة ثانية\nوهل تنصحوني اطبق فيهم ولا لا ؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/178134/1", "user": "Jehibaru", "ts": 1511119867000, "tid": 178134, "pn": 1}}', 1511119867000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429953-ee398', 'stk-hassan_al_yagoub', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nمعاكم حسن آل يعقوب … احد خريجي برنامج اديسون للتطوير الهندسي لشركة جنرال إلكتريك بقسم الطاقة و الماء “Power &Water”. خلال رحلتي للتقديم على البرنامج في سنة 2011 واجهت صعوبات لمعرفة معلومات عن البرنامج وخاصة باللغة العربية، ولهالسبب حبيت أوضح البرنامج بأكثر قدر من التفاصيل وأجاوب على أسئلتكم بخصوص البرنامج.\n\nفي شركة جنرال الكتريك فيه عدة برامج للتدريب مثل برنامج “OMLP” و\"CLP\" و “ITLP”.\n\nماهو برنامج الاديسون؟\n\nبرنامج الاديسون هو برنامج تقني، مدته سنتين ونص راح تشتغلو فيه 5 وظائف مختلفه كل وظيفه مدتها 6 شهور. الوظايف راح تغطي التصميم، الاختبار، التحليل أو الاستشارات الهندسية المتعلقه بالتوربينات Gas Turbines. خلال فترة عملكم راح تكونو ببرنامج تدريبي نظري مكثف لمدة لمدة 4 سنين “سنة بعد التخرج من البرنامج”. بشرح ليش بعد مااتكلم عن المقابلة.\n\nفترة المقابلة:\n\nالمقابلة بالنسبة لي كانت 4 مقابلات:\n\nأول مقابلة لي كانت للتأكيد على المعلومات في الCV. أسئلة بسيطة، وين إشتغلت، معدلك، سنة التخرج، عن الوظايف الي اشتغلتها “الاديسون يتطلب سنة خبرة وبالنسبة لطلاب البترول ففترة الكوب اب تغطي”.\n\nالمقابلة الثانية كانت تتكلم عن شخصيتي، وعن بعض الامور الي تتكلم عن دوري بالفريق ودوري القيادي.\n\nالمقابلة الثالثة كانت مقابلة تقنية مع مسؤول بامريكا وكانت اصعب مقابلة. بهذي المقابلة، جهز ورقة وقلم وويبكام. راح يسالك عن نفسك، مشروع تخرجك، خبرتك وراح يعرض عليك سؤال يا إما متعلق بمشروع تخرجك أو راح يطلب منك تحل سؤال تقني يقيس عليها مستواك بالهندسة.\n\nالمقابلة الرابعه هي تكون اكثر كشرح لك للوظيفة وانهم يتاكدوا انك فعلا مستعد للتضحيات تسويها \"مثلا بالنسبة لي اضطريت اني ااجل زواجي لبعد التخرج من البرنامج، بسبب ضغط العمل.\n\nاذا عديت كل هالمقابلات… الف مبروك !!\n\nقبل مااشرح كيف نظأم البرنامج، بغيت اوضح انك راح تكون مسجل في برنامجين للتدريب، برنامج الاديسون EEDP وبرنامج ACE\n\nالEEDP او الاديسون هو مثل البرامج التدريبية الثانية راح تشتغل 5 وظايف وراح تاخذ 5 دورات تدريبية مدة كل وحدة منهم اسبوع. مدة البرنامج سنتين ونص.\n\nمتطلبات انك تتخرج من الاديسون:\n-العمل ب5 وظايف مختلفة. وظيفتين بتكون بامريكا و 3 وظايف بالشرق الاوسط.\n-اكمال B course “راح اشرحه بالقسم الثاني”.\n-اكمال كورس الsix sigma.\n-اكمال كورس foundation of leadership. “من اجمل الدورات التدريبية الي حضرتها بحياتي” … هذا شرح للكورس\nGE CLP BLOG - Blog\n-اكمال كورس Eng@ge وهو عبارة عن بطولة للروبوتيكس وبنفس الوقت مجال تتعرف فيها على ناس من برنامج الاديسون من شركات مختلفه من جي اي.\nENG@GE Run 1 Video - YouTube\n-اكمال كورس teardown وهو كورس يختلف من سنة لسنة … وقت ماحضرته كان فيه شرح مفصل عن وظيفة الfield engineer و المشاكل التقنية لمحطة الكهرباء\n-اكمال كورس powerplant fundamentals وهذا الكورس يشرح كل شي متعلق بمحطة الكهرباء وجدا مكثف ومدته اسبوع.\n\nالACE هو التدريب النظري ومدته 4 سنوات. يتضمن انك تدرس 34 نظري في اول سنة، و 15 كورس بالسنة الثانية وتقدم مشروع جماعي ومشروع تخرج شخصي. باختصار انت راح تخلص\n\nمتطلبات انك تتخرج من ACE:\n1- انك تنهي متطلبات A course بالنسبة للسنة الاولى.\nA course هو عبارة عن 34 كورس … راح تدرس فيها تقريبا عن كل شي متعلق بالهندسة الميكانيكية او الكهربائية وراح تاخذ عدة كورسات متعلقة بالرياضيات. هذا الكورس من دون مبالغه ممكن تكون اصعب سنة لك بالشركة وبسبب انك راح تاخذه بامريكا وماراح تكون عندك ارتباطات عائلية راح يكون اسهل. الكورس راح يكون اسبوعي بحيث انك تحضر محاضرة كل ثلاثاء لمدة اربع ساعات. وتشتغل على الواجب كل يوم بعد ساعات الدوام مع الجروب الي تشتغل معاه “بالعادة نطلع من الدوام الساعة 9 الى 11 الليل.” بعدها راح تشتغل على الريبورت بالويكند وراح ياخذ منك من 5 الى 10 ساعات حسب سرعتك وصعوبة المادة. راح يكون فيه اختبار نهائي لكل 17 كورس بحيث ان معدل الدرجات راح تحسب ك3 ساعات لدرجة الماجستير.\n\n2- انك تنهي متطلبات B Course بالنسبة للسنة الثانية.\nB course هو عبارة عن\n\n* 15 كورس … الكورسات اقل نظرية واكثر تطبيقيه من ناحية المعلومات … وراح تاخذ اسبوع منها ككورس تطبيقي بmachine shop. را\n* مشروع تشتغل فيه مع 4-5 اشخاص لمدة 8 شهور وهو بالعادة يكون تصميم لقسم او معدة جديدة.\n*اكمال كورسين على الاقل للماجستير واثنين منهم يكونو متعلقين بموضوع واحد Minor.\n\n3- انك تنهي متطلبات C Course قبل نهاية السنة الرابعه\n*اكمال مشروع تخرج “ACE Project” وهو عبارة عن مشروع او بحث شخصي “على الاقل 90% من المشروع لازم تكون منفذه بنفسك بدون مساعده”. خذ ببالك انك تقدر تختار اي مشروع وتقدر تخلص من مشروع التخرج قبل ماتخلص حتى من الـA Course.\n\n*اكمال درجة الماجستير باحد الجامعتين North Carolina State University أو Georgia Institute of Technology.\n\nراح احاول ان شاء الله اشرح طبيعه الروتيشنز واجيب قد مااقدر من الستفسارات منكم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ges-edison-engineering-development-program/170303/1", "user": "Hassan_Al_Yagoub", "ts": 1444324498000, "tid": 170303, "pn": 1}}', 1444324498000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p791523-ee398', 'stk-e.p.e', 'EE 398', 'info', '{"desc": "عزيزي, نظام Cooperative training في جامعة القصيم ولااعلم عن جامعة الملك سعود يسمح بعد عدد ساعات معينة وغير مسموح بتاتا فيه بعد الإنتهاء من جميع المقررات\nيعني طالب على الخطه المقترحة من قبل الكلية …يسمح للطالب بالتدريب التعاوني بعد المستوى الثامن ,ويتبقى له المستوى العاشر وآليا تكون عدد ساعاته 18 ساعة هي ثلاث مواد Elective وثلاثه إلزامية…\nإذا اردت انت والإخوان الخطة الدراسية لهندسة القوى الكهربائية في جامعة القصيم مستعد أن أرفقها\n\nفائق الإحترام والتقدير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/102368/42", "user": "E.P.E", "ts": 1297787119000, "tid": 102368, "pn": 42}}', 1297787119000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504446-ee398', 'stk-electrical_engineeer', 'EE 398', 'info', '{"desc": "ابلوني 3 كلموني من جوال أحدهم , أول سؤال تكلم عن نفسك\nتكلمت عننفسي وعن الCOOP و أكثر اسألتهم جات عليه و احتمال لأني اشتغلت في الكهرباء (اختبارات المحطات) CSD ولأن عملهم في هذه الأشياء سألوني عنها. بالنسبة لي كل أسئلة التكنكال على الCOOP و بعدها أسئلة معتادة مثل عندك مانع في التنقل لمسافات يوميا وهل عندك أسئلة لنا ؟ وشكروني وانتهت المقابلة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/schneider-electric-fresh-graduate-program/180627/42", "user": "electrical_engineeer", "ts": 1546492968000, "tid": 180627, "pn": 42}}', 1546492968000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p940345-ee398', 'stk-barhomitto', 'EE 398', 'info', '{"desc": "السلام عليكم … إخواني حبيت أتكلم في موضوع السينيور بروجكت (ee411)\n\nهو في الأساس -حسب الخطة- مفروض يكون في الترم الأخير للطالب.\n\nلكن من ناحية البري-ريكويست… مافي أي شي مطلوب غير إنك تكون سينيور.\n\nأنا سمعت -والله أعلم- إن الأفضل:\n\n1- تكون مخلص كل مواد ليفيل 3 قبل ما تاخذه.\n\n2- أو إنك تاخذه مع آخر مواد ليفيل 3 الي باقية عليك في نفس السمستر … حتى تكون ملم بكل فروع الكهرباء.\n\nأنا فكرت أمشي على السيناريو الثاني وبسيوها قبل الكوأب.\n\nنبي رأيكم للي أخذ البروجكت … ايش مفروض تكون مخلص؟ وإيش الأحسن؟ وإيش هي طبيعة المشروع غالبا؟\n\nنبغى منكم تجارب مريتو فيها … للفائدة العامة يعني فضلا لا أمرا.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/115932/1", "user": "Barhomitto", "ts": 1322687064000, "tid": 115932, "pn": 1}}', 1322687064000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p924907-ee398', 'stk-majcom', 'EE 398', 'info', '{"desc": "بالنسبة لك اخوي cortez1408\n\nاولا ماشاء الله تبارك الله و بالتوفيق للجميع\n\nشركة الربع الخالي الصراحة ما اعرف عنها اي شيء\n\nاما بالنسبة لشلمبرجير و GE الاثنين من افضل الشركات …\n\nGE حسب ما سمعت انها افضل شركة مزودة للمعدات الكهربائية على مستوى العالم\nطبعا فيها شغلات ميكانيكة واجد لا تخاف (شغلات تورباين و غيره)\n\n-الشركة امريكية و معروفة لا غبار عليها رواتبها مغرية (سمعت 14 الف فل بكج) و الله اعلم\n-عندهم برامج تدريبة على مستوى عالي جدا\n-امكانية ان تشتغل في نفس تخصصك بما انك هندسة ميكانيكية\n-كل اللي اخذوا COOP في هالشركة يمدحون فيها\n\nبالنسبة لشلمبرجير فانا اشتغلت معاهم فترة بسيطة و كانت تجربة حلوة صراحة\nلكن هذا يعتمد على الشخص نفسه\n\n-هل عندك القابلية ان تشتغل في مناطق نائية وسط الصحرا ء او وسط البحر ؟\n- و بنظام الشفتات او حتى on call ؟\n-لساعات طويلة (12 ساعة على الاقل) و اذا وايرلاين اطول اكيد\n-هل عندك مشكلة انك تشتغل خارج اطار تخصصك ؟\n- هل عندك مشكلة تعمل في بيئة خطرة (احتراق ، غازات سامة …الخ)؟\n\nكل هالامور لازم تاخذها بعين الاعتبار و اما ميزات شلمبرجير فهي تماما مثل ge من ناحية\nالتدريب و الترقية …الخ\n\nطبعا لما نجي نقارن بينهم\n\n- فسنجد أن الميزة الوحيدة لشلمبرجير على GE هو الراتب <<< و هذا يمكن يكون سبب كافي للبعض بان يفضل الشركة هذي\nو ربما يكون سبب غير كافي للبعض الآخر ، و زي ما قلت انه يعتمد على الشخص نفسه\n\n- لكن شلمبرجير فيها عيب ، انه خلاص هذي بتكون خبرتك (محدودة) في مجال معين\nبعدين راح يكون صعب انك تغير\n\n- اما GE فمشاريعها تدخل في ال power plant و petrochemical بالاضافة الى oil & gas\nيعني الخيارات عندك اكثر في المستقبل\n\nاسف اني طولت عليك … في الاخير القرار المناسب يعتمد على الشخص نفسه و على\nالاشياء اللي تهمه و اللي بيحصل عليها من الوظيفة نفسها .\n\nبالتوفيق للجميع 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/114286/7", "user": "majcom", "ts": 1319477766000, "tid": 114286, "pn": 7}}', 1319477766000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1073338-ee398', 'stk-user7335', 'EE 398', 'info', '{"desc": "وعليكم السلام… حاليا انا كواب بالشركة… الشركة أسست قبل اكثر من 170 سنة في فرنسا… عموما مع تاريخها الكبير والحافل …الا انها في السعودية لا تقارن بالام في فرنسا… ما اطول عليك\n\nاول شيء مين سوا المقابلة معاك؟\n\nثانيا بالنسبة للمصنع فهم يمتلكون مصنعين قيد التشغيل والثالث تحت الانشاء… المصنعين قريب من بعض… وهم بالصناعية الثانية بالرياض… على طريق الخرج… قريب من مصفاة ارامكو.\n\nحبيت استفسر عن الامان الوظيفي في الشركة؟ وعن الزيادة السنوية ؟\nالشركة لها مشاريع مع سكيكو كثيرة… ومن ضمن مشاريعها في جامعة نورة ومدينة الملك عبدالله الاقتصادية وايضا جامعة الملك سعود… اكثر مشاريعها تندرج ضمن حماية الشبكة و الاستفادة من الطاقة بشكل افضل. امانها الوظيفي متوقف على إنتاجية الموظف… وايضا على استمرار سكيكو في ضخ المشاريع لها, واعلى علاوة تقريبا 7% , والغالب كما ذكروا لنا الشباب 4%.\n\nوكيف خبرتها تعتبر؟\nبالنسبة لمهندسي الكهرباء بمجال الطاقة, تعتبر خبرة ممتازة, خصوصا في معرفة طرق حماية الشبكات و ربطها ببعض…وفيها قسم اوتميشن… سكيكو تعتبرها خبرة لا يستهان بها… خصوصا ان الشركة تعمل لسكيكو اغلب مشاريع الحماية… والشركة المنافسة لها هي ABB وهي شركة قوية, ويحاولون الامساك ببعض خبرات شنايدر السابقة.\n\nفي الأخير… اذا كان عقدك قريب مع شركة اكبر يعني خلال شهر الى شهرين, فربما توقيع العقد مع شنايدر لا يفيدك بقدر كبير… لكن اذا كنت ستبقى في شنايدر اكثر من 5 شهور , ربما يكون في مصلحتك التوقيع مع شنايدر, في الغالب يوظفوا السعودي لجعله مهندس مسوق للجهات الحكومية.\n\nكلمة أخيرة… لا تغتر بما يخبرونك به في الاسبوع التعريفي بعد التوقيع… أنهم يعملون باحترافيه , لانهم سيضهرون لك ان الشركة لا ينافسها أحد (أحد أساليب ال Show) … بالتوفيق … وأي أسئلة, أكون في الخدمة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/129399/2", "user": "user7335", "ts": 1343531239000, "tid": 129399, "pn": 2}}', 1343531239000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1253662-ee398', 'stk-user5422', 'EE 398', 'info', '{"desc": "شكرا لك اخوي Poweeer\n\nبس عندي سؤال خصم التأمينات من الفل باكيج ولا من الاساسي , ويا ليت لو تقول لي من فين اجيب معلمومات اكثر عن pdp\n\nالله يبارك فيك يا X RAY\nالمقايلة بسيطه جدا , أتكلم عن نفسك و الكوأب و السينيور بروجيكت , بعدين يساولني بعض الاسئله المتعقله في الكوأب و البروجيكت وبس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/148019/6", "user": "user5422", "ts": 1376937158000, "tid": 148019, "pn": 6}}', 1376937158000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p354857-ee398', 'stk-user985', 'EE 398', 'info', '{"desc": "بعد التحية\n\n(( فرحة ما تمت ))\n\nلم يكن يوم الخميس كغيرة من الايام … فمعاناة الحجوزات كانت معجزة بالحقيقة … المهم انني وصلت الى المنطقة الشرقية وتوجهت الى الهولدي ان مباشرة … لاجد ثالثة الاثافي تستقبلتي …\n\nتفاجات في البداية بان البنك هو بنك البلاد … خير وبركة … الجزيرة او البلاد كلها بنوك اسلامية …\n\nقال لي المسوؤل بان المقابلات لبرنامج التدريب التعاوني وليس للتوظيف وان التوظيف انتهينا منهم يوم الاربعاء ولا توجد فرصة لتخصصك نريد هندسة حاسب و ادارة … ولا نريد هندسة كهربائية …\n\nشرحت للمسوؤل وضعي فكلمني بامانة بانه لا يملك من الامر شئ ولكنه سيجري معي مقابلة - اكراما لخاطري - وسينقل الصورة لروؤسائه واعتذر لي عن تكبدي مشقة السفر وما عانيته من انتظارات في مطارات المملكة في سبيل الحصول على الوظيفة المزعومة … وقال لي والله الذي ليس له شريك انه لا يعلم عن هذا الامر…\n\nختاما يا دكتور الخروبي ويا قسم شوؤن الخريجين … لا ادري ما اذا اقول لكم … معلومات مغلوطة اسافر لاجلها 1500 كلم تقريبا وارجع خالي الوفاض …ليتكم على الاقل اوردتم لي المعلومة الصحيحة وكفيتوني هذا(( المشوار اللي على الفاضي ))\n\nاللهم آجرني في (( وظيفتي )) واخلف لي خيرا منها\n\nوالحمد لله على كل حال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68771/55", "user": "user985", "ts": 1232730077000, "tid": 68771, "pn": 55}}', 1232730077000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1028273-ee398', 'stk-see', 'EE 398', 'info', '{"desc": "انا توظفت في abb لفترة من الزمن ومن ثم تركتها لوجود فرصه افضل\n\nقدمت عليهم عن طريق يوم المهنه وقاموا بالاتصال علي بعد شهر تقريبا\n\nاماكن العمل هي : المنطقة الشرقية…الرياض (المقر الرئيسي والمصنع) والغربية(جده)\n\nطبعا مكتب التوظيف هو في الرياض في المصنع ويتم هنالك المقابلة الشخصيه والقبول\n\nالمميزات المادية: الراتب الاساسي من 7000 الى 9000 يعتمد على الادارة التي تم قبولك فيها وطبيعة عملك والمقابلة الشخصية\nمع البدلات الراتب صافي مع اقتطاع التأمينات يوصل 10200 ريال طبعا يكون اكثر لو كانت اداراتك شغل فيلد\n\nالخبرة العلمية: لديهم خبرة علمية اكثر من رائعة بسبب ضغط العمل الرهيب\n\nبالنسبة للمهندس الكهربائي فهو المطلوب الاول لدى شركة abb\n\nمميزات اخرى:\n\nيصرف مبلغ لكل طفل من اطفالك سنويا والحد الاقصى 3 اطفال\nيوجد بونص سنوي والنسبه تختلف من ادارة الى اخرى\nالدورات التدريبية تستطيع طلبها بنفسك بعد الموافقه عليها من رئيسك\n\nالعيوب:\n\nجو العمل مشحون وذلك لتعدد الجنسيات والاديان والمنافسه الشديدة على التميز وهذا سبب احتكار اغلب الموظفين للمعلومة خصوصا للخريج السعودي الجديد\n\nالسعودي غير مرغوب فيه بحد كبير ولكن تستطيع اثبات وجودك\n\nلا يوجد سلم وظيفي واضح…لا يوجد زيادة سنوية واضحة للراتب… يعني على حسب الارباح وعلى حسب مزاج المدير\n\nيوجد دوام يوم خميس لكل اسبوعين ( اسبوع دوام واسبوع اوف)\n\nبالنسبة للماستر…يوجد لديهم برنامج ابتعاث (لغير الموظفين) يعني برنامج تعاوني…الموظف لايمكن ان يبتعث للماستر…واعرف اكثر من شخص استقال بسبب انه حاب يكمل ماستر\nاتمنى ان اكون افدتك يا اخي الكريم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abb/123846/9", "user": "sEE", "ts": 1335329896000, "tid": 123846, "pn": 9}}', 1335329896000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p275106-ee398', 'stk-user889', 'EE 398', 'info', '{"desc": "Requirements and Eligibility\n\nThe following criteria (as given in the KFUPM Undergraduate Bulletin) should be met before a student is considered eligible for admission to the coop work programs:\n\nThe coop program must be completed before the last semester at KFUPM.\n\nCompletion of a minimum of 85 credit hours.\n\nCompletion of special department requirements (ENGL 214, EE 303, EE 360, and EE 370) and at least three of the following courses (EE 340, EE380, EE390, EE 417, EE 462, and EE 463).\n\nHaving a major or cumulative GPA of 2.00 or higher, and\n\nNot being subject to dismissal for academic causes.\n\nهذا اللي لقيته عندكم… بس ننتظر التأكيد من اي طالب AEE", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/63781/2", "user": "user889", "ts": 1213657974000, "tid": 63781, "pn": 2}}', 1213657974000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1251068-ee398', 'stk-majdi90', 'EE 398', 'info', '{"desc": "عزيزي سلطان\nأنا ماني في موضع يقدم نصائح لأني بدون تجربة (في مرحلة التدريب التعاوني 🤠)\nلكن عن نفسي صار عندي قناعة أنو أفضل مجال للعمل بالنسبة للمهندسين هو قطاع الطاقة (النفط والغاز والكهرباء) وبعدين يجي الصناعة والخدمات. وجونسون كنترولز صحيح انهم يهتمون بالموظف وبيئة عملهم اتوقع أفضل من الكهرباء بكثير … لكن الخبرة المكتسبة ارجح انها للكهرباء أكثر بكثير.\n\nوحقيقة أتفق مع ماراثون في جزئية ان جونسون كنترولز خيار ممتاز بعد شركات الطاقة والصناعة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/147724/8", "user": "Majdi90", "ts": 1375448696000, "tid": 147724, "pn": 8}}', 1375448696000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1501621-ee398', 'stk-user10191', 'EE 398', 'info', '{"desc": "بسم الله الرحمن الرحيم\nتخصصي هندسة كهربائية وحاليًا في الفصل 173\\181 أطبق عند شركة Halliburton\nالتطبيق في الـBase في سيهات\nمكافأة التدريب 1250 ريال شهريًا\nطبعًا فصّلوا لنا Coverall وأعطونا Safety Shoes و الـHelmet\nالتدريب اللي شفته ما له علاقة بالهندسة. في الخطة راح نمر على 4 ورش\nهذي الورش لصيانة الآلات والقطع اللي تجي من الرق\nطبعا بما أننا متدربين، شغلونا عمّال، نهائيًا ما اشتغلنا شيء في الهندسة إلى الآن (الأسبوع 19) وما راح نشتغل حسب الموجود في الخطة\nشغلتنا نفك القطع وننظفها من الزيت والطين المستخدم في الحفر ونشيل ويا الفنيين القطع وننقلها معهم وننظف الأرضيات والمعامل ونروح وين ما موجود نقص عُمّال في الورشة\nونسيت حاجة، ما فيه مهندسين في الورش أبدًا\nالمهندسين في مكاتب فوق لوحدهم. نقدر نروح لهم إذا نبي بس ما نشتغل معهم. كل شغلنا داخل الورش\nإن شاء الله وصّلت اللي عندي\nواللي عنده أي استفسار يتفضّل 🤴", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-halliburton/180448/1", "user": "user10191", "ts": 1540915180000, "tid": 180448, "pn": 1}}', 1540915180000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1443188-ee398', 'stk-user10276', 'EE 398', 'info', '{"desc": "انا حاليا COOP في الكهرباء الفكرة طول الله أعماركم , انه اول ما اخذت الفرصة كتبوا لنا مكافأة في الفرصة\n\nويوم رحنا نقدم خطاب الجامعة للشركة قالوا حدث تطور في الموضوع والمكافأت صارت فقط للطلاب الأونرز , الموضوع ذا صار بسبب مدير التدريب الجديد ما اعرف اسمه لكنه جديد وحب يثبت نفسه وعمم الكلام ذا على مسؤولين التدريب في كل المناطق\n\nالمهم , اني وافقت بدون مكافأة بحكم اني ابغا التدريب عند أهلي , الكلام ذا قبل التدريب باسبوع , وقبل التدريب بيومين تواصل معي مسؤول تدريب (جدة) الي قدمت عن طريقهم قال حنا كلمنا مدير التدريب وناقشناه ان الموضوع فيه ظلم و قال خلاص تمشي المكافأت للمتدربين الحاليين , لكن من التدريب القادم راح يخضع المتقدمين لإختبارات ومقابلات شخصية وعلى غرارها نقرر\n\n+ المكافأة تكون دفعة كاملة بعد اكمال التدريب\n\nوبس 🚬", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/172395/8", "user": "user10276", "ts": 1456479417000, "tid": 172395, "pn": 8}}', 1456479417000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1390811-ee398', 'stk-user4632', 'EE 398', 'info', '{"desc": "انا طبقت كواب في الشركة\nوتخصصي ميكانيكل\nكمهندس مدني صراحة مدري وش يبغون فيك ههههههههه\nيعني هي الصراحة تصلح اكثر شيء للكهرباء والصناعية\nالميكانيكل كنا نشتغل في قسم التصنيع\nرواتبهم فل باكيج بين 10800 الى 12000\n-------\nاتذكر فيه مصلى كانت فيه مخططات المطار والمناطق المجاورة مدري وش دخل الشركة تحتفظ فيها\nتاكد من القسم اللي بتروح له… لانها غريبة جدا والله\nوالله يوفقك 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/164084/2", "user": "user4632", "ts": 1408397876000, "tid": 164084, "pn": 2}}', 1408397876000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p620353-ee398', 'stk-altayar', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nصباح \\ مساء الخير لكل الكهربائيين >>>>> اقصد المهندسين الكهربائيين :d\n\nالموضوع وما فيه اني ابغى سامبل ريبورتز للكوأب\n\nويفضل للي ماخذين الكوأب في ارامكو\n\nالفايده هي اني اخذ فكره عن الموضوع\n\nوانشاء الله استفيد منها انا وغيري من الطلاب\n\nفا اللي عنده لايبخل علينا يرفعه لاي موقع او التراكر (الشير )\n\nولكم جزيل الشكر 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sample-coop-reports-request/89215/1", "user": "altayar", "ts": 1275463391000, "tid": 89215, "pn": 1}}', 1275463391000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1291682-ee398', 'stk-zizo_791', 'EE 398', 'info', '{"desc": "Coop opportunities at Unilever Factory in Jeddah for the following majors:\n1- MIS\n2- Mechanical Engineering\n3- Electrical Engineering\nplease send your CV to the following\nemail : hamza.zeidan@unilever.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-opportunities-at-unilever/152760/1", "user": "zizo_791", "ts": 1385053366000, "tid": 152760, "pn": 1}}', 1385053366000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1469071-ee398', 'stk-user10275', 'EE 398', 'info', '{"desc": "Location: Riyadh, AR Riyad, Saudi Arabia\nCompany: Cisco Systems, Inc.\nAdditional Location(s) or Information: Start Date: February 2017 Duration: 7 Months Job Category: Sales Level of Experience: Intern\nWhat you need to be eligible:\n\nYou must be in a position to graduate from your degree by the start date of the program, or have the internship as the last prerequisite to graduate.\n\nYou must be available full time for the period of the program.\n\nYou will preferably hold a degree such as Bachelor’s (BS/BA/etc.) or master’s degree in:\n\nElectrical, Computer, or Networking Engineering; Computer Programming; Information Technology; Management Information Systems; Computer Science; Business and Management; HR ; Finance; Marketing and any other Economics related degrees.\n\nYou are fluent in English and the Arabic.\n\nYou must be a Saudi National.\n\nInternship - Technical & Business Saudi Arabia Job", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/87", "user": "user10275", "ts": 1488110971000, "tid": 174980, "pn": 87}}', 1488110971000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473126-ee398', 'stk-eng_mohammed_al-sham', 'EE 398', 'info', '{"desc": "Dear All,\n\nI am looking for Summer & Coop Engineers for the following majors:\n\nMechanical Engineering\nIndustrial Engineering\nElectrical Engineering\nIf you are interested, send you CV to: sjobs@qaryansteel.com.\n\nNote: please make sure you type COOP or SUMMER -“Major”-“Name” as subject of your email.\n\nWe are looking for candidates who really want to work & learn, no free rides!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/145", "user": "Eng_Mohammed_Al-sham", "ts": 1494766090000, "tid": 174980, "pn": 145}}', 1494766090000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1362916-ee398', 'stk-eng_why_not', 'EE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\nالحمد لله رب العالمين, والصلاة والسلام على سيدنا محمد الصادق الوعد الأمين, اللهم لا علم لنا إلا ما علمتنا إنك أنت العليم الحكيم, اللهم علمنا ما ينفعنا, وانفعنا بما علمتنا, وزدنا علماً, وأرنا الحق حقاً, وارزقنا اتباعه, وأرنا الباطل باطلاً, وارزقنا اجتنابه, واجعلنا ممن يستمعون القول فيتبعون أحسنه, وأدخلنا برحمتك في عبادك الصالحين.\n\nرواد هذا الصرح العظيم أتمنى ان اكون ضيفاً خفيفاًِ عليكم اعين و اعاون و ان شاء الله تنتفعوا بهذا الموضوع البسيط\nسوف اعرض لكم تجاربي من تقديم و مقابلات مع الشركات التي اكرمني الله القبول منها مع العلم اني متخصص في الهندسة الكيميائية و متخرج الترم الماضي\n\nبسم الله على بركه الله\n\nسوف اقسم الموضوع الى 5 اقسام:\n1- كتابه الغرض من العمل مع السي في (الريسمي) خطوه بخطوه\n2- الاستعداد للمقابلات وكيفه التجهيز الايجابي لها\n3- تجاربي الشخصية\n4- الاختيار الأمثل\n5- نصائح محب\n\nالقسم الاول: كتابه الغرض من العمل مع السي في خطوه بخطوه\nلا يخفى عليكم اهميه كتابه السي في ولكن يغيب عن الكثير منا اهميه تحضير و كتابه الغرض من العمل\nIt’s called a Cover Letter or Statement of purpose\nلكي تحضر جيداً لكتابه الغرض من العمل، ينبغي عليك معرفه القسم الذي سوف تعمل فيه المقابلة\nFor example: I am going to have an interview at the project management department\nاسأل نفسك ماذا سوف تعمل في هذا القسم؟ و ماهي المتطلبات و شروطه؟\nخلال هذه الورقة تكتب طموحاتك و تطلعاتك للعمل في هذا الشركة ولماذا تريد انت تعمل في هذا القسم بالتحديد\nهذه امثله لكتابه هذه الخطاب\nhttp://jobsearch.about.com/od/coverlettersamples/a/coverlettsample.htm\nو هنا للسي في\nhttp://jobsearch.about.com/od/sampleresumes/a/sampleresume2.htm\nالجميل في هذه الأمثلة، انها متعددة لتخصصات مختلفة و يوجد بهذا الموقع بعض من النصائح المهمة و التي قد نكون غير ملمين بها\nمن وجهـة نظري المتواضعة قبولك المبدئي في الشركات يتعمد على قوه الغرض من العمل مع السي في\n\nالقسم الثاني: الاستعداد للمقابلات وكيفه التجهيز الايجابي لها\n1- التوكل على الله و الاستخارة\n2- معرفه القسم الذي سوف تقابله\n3- البحث عن عمل هذا القسم والالمام بمخرجاته\n4- معرفه نوع نشاط الشركة على الاقل ابجديات عملها\n5- الثقة بالنفس و عدم التوتر\n6- النوم الجيد قبل المقابلة لكي تكون جاهز 100٪ ان شاء الله\n\nالقسم الثالث: تجاربي الشخصية\nعملت 4 مقابلات من اصل10 ولله الحمد وهم ساتورب و سابك و ارامكو و شلمبرجير . و لقد اعتذرت من بيكر هيوز و وذرفورد و معادن و الصحراء و كريستال وهني ويل\n\nابدء اولا بشركه ساتورب\nالكل يعرف من هي ساتورب مشروع ضخم وجميل من اروع ما شهدت في قطاع النفط و البيتروكيميكال\nمع نهايه شهر فبراير 2014 انتهيت من تعبئه طلب الالتحاق (الابلكيشين) و تم الاتصال بي من قبل موظف الموارد البشرية لعمل مقابله معهم (تمت المقابله خلال اسبوع من تعبئه الابلكيشبن) و الحمد لله ذهبت الى مقر الشركة لعمل المقابلة الشخصية مع قسم الاوبريشين سينسور انجينيرز ( سعودي و جزائري) و للأمانة كانوا في قمه الاخلاق والتواضع. استمرت المقابلة لمده 45 دقيقه على النحو التالي: عرفنا بنفسك؟ ما هو تخصصك؟ من اين حصلت على درجتك العلمية؟ لماذا اخترت تلك الجامعة؟ لماذا تخصصت في الهندسة الكيميائية؟ تكلم عن مشروع التخرج؟ لماذا اخترت هذا المشروع و ما الهدف منه؟ ارسم لنا الفلو شارت تبع الديزان؟ ماهي المنظمات الطلابيه التي اشتركت بها؟ وماذا كان دورك بها؟ هل عملت كوااب خلال دراستك الجامعيه؟ كيف ترى نفسك هنا كا مهندس فرش تنافس المئات من الخريجين لدى ساتورب و كيف ترى نفسك ك مهندس عمليات\n(Process Engineer)؟\nهل تود الحصول على الشهادات العليا؟ ولماذا؟\nوبحكم اني من انني لست من سكان الشرقية تم سؤالي هل تمانع من العمل في الجبيل؟\nو خلال يومين من المقابلة استلمت العرض الرسمي من الشركة\n\nالتجربة الثانية مع سابك\nاتممت التقديم على موقع سابك في منتصف فبراير 2014 والحمد لله اتتني فرصه للمقابلة من شركه صدف التابعة لسابك في الجبيل. بعد مقابلتي بيومين من ساتورب، ذهبت لعمل المقابلة مع صدف التي تعتبر من افضل شركات سابك. المقابلة الشخصية مع قسم الاوبريشين مدير المصنع و سينسور انجينير ( سعوديين) استمرت المقابلة لمده ساعه او اكثر بقليل. و للأمانة تم فصفصت ما تعلمته خلال دراستي الجامعية خلال هذه المقابلة ( بالعامية حللوني صح ) بدء من ماتيريال بالانس الى هيت و ماس ترانسفير و انتهاءَ بمشروع التخرج مع الاخذ بالاعتبار الكيمياء والبوليمرز. المقابلة كانت تخصصيه اكثر من شخصيه.\nالحمد لله استلمت العرض الوظيفي خلال شهر من المقابلة ولله الحمد\n\nالتجربة الثالثة مع أرامكو\nفي بدايه شهر فبراير 2014 استلمت رساله على الايميل من أرامكو (اعلان) اذا كانت لدي الرغبه في العمل لديهم. و بالفعل اتممت من التقديم من خلال موقعهم في نفس اليوم. وخلال اسبوع استلمت ايميل دعوه لحضور ميغا كامبين في فندق ماريوت بالخبر في يوم 17 فبراير حضرت المقابلة معهم. كان هناك حضور كثيف من خريجي الجامعات من داخل و خارج المملكة. بعد التسجيل عند المدخل في خلال نصف ساعه توجهت لعمل المقابلة الشخصية مع قسم OSPAS\nالمقابلة استمرت لمده نصف ساعه و كانت مع اربع مهندسين و في البداية عرفت بنفسي.ما هو تخصصك؟ متى تخرجت؟ من اين حصلت على درجتك العلمية؟ لماذا اخترت تلك الجامعة؟ لماذا تخصصت في الهندسة الكيميائية؟ تكلم عن مشروع التخرج؟ لماذا تريد العمل معنا؟ ماذا تعرف عن قسمنا؟ هل ترغب في اكمال دراستك الجامعية؟ حدثنا عن البرامج التي تحسن استخدامها؟ هل عملت كوااب من قبل؟ وقد اعلموني اني سوف استلم من هم رد قريبا. و بالفعل استلمت الموافقة الرسمية ولله الحمد من القسم خلال نهاية اليوم من احد المهندسين الذي كان موجود في المقابلة.\n\nالتجربة الرابعة شلمبرجير\n\nفي البداية هذه بعض النصائح من موقع الشركة\nhttp://careers.slb.com/experiencedprofessionals/~/media/Files/Careers/leaflets/Interview%20tips.ashx\nللتحضير لمقابله هذه الشركة العملاقة استعنت بمواقع ساعدتني كثيراً للتحضير الأمثل\nhttp://www.glassdoor.com/index.htm\nحيث بالإمكان البحث عن اي شركه عالميه لاستعراض تجارب، مقابلات، رواتب (البعض منها) واشياء مفيده من الممكن ان تخدمك لأخذ إنطباع أولي عن أي شركه عالميه\nوهذا الرابط بالأسفل يعطي بعض من التجارب الجميلة لمتقدمين لشركه شلمبرجير\nhttp://www.glassdoor.com/Interview/Schlumberger-Field-Specialist-Interview-Questions-EI_IE588.0,12_KO13,29.htm\nتجد عن المتقدمين للكواب او فرش او خبير من مختلف دول العالم\nوهنا بعض الأسئله مع الاجوبه المحموده و المذمومه ومدى تأثيرها على المقابله بالإضافه لبعض المواقف و النصائح\nhttp://interview-questions1.co.uk/Schlumberger/interview+questions\nو اخيرا هذا الموقع يشرح ما يمكن توقعه خلال المقابله مع بعض الإرشادات و التعليمات\nhttp://www.petroleum-engineering.net/schlumberger-interview-how-schlumberger-will-interview-you/\n\nاتممت طلب الالتحاق عن طريق موقعهم في نهايه مارس 2014 وجاني اتصال منهم بعد اسبوع استمرت لمده ساعه. كلمتني موظفه الموارد البشرية لمده ساعه تقريباً. في البداية قالت لي تحدث عن نفسك؟ ما لذي دفعك لطلب الالتحاق لـ شلمبرجير ؟ هل عملت كوااب؟ ماذا تعرف عن شلمبرجير ؟ هل لديك مانع في العمل في الفيلد؟ او العمل في مواقع مختلفة؟ هل تمانع في العمل في داخل و خارج المملكة؟ ماهي اللغات التي تتحدثها؟ و أين تعلمتها؟ حدثني عن دراستك؟ هل شاركت في أعمال تطوعيه؟ ماهي نقاط ضعفك؟ قوتك؟ ما رايك في العمل الجماعي و الفردي؟\nوقبل إنهاء المكالمة دعتني لحضور مقابله شخصيه في الشركة في نفس الأسبوع (بعد يومين). و هنا نأتي للمقابلة الثانية\nحضرت لمقر الشركة وقابلت 3 مهندسين من جنسيات مختلفة مع موظفه الموارد البشرية. كان عدد المتقدمين 7 في ذلك اليوم ومن تخصصات مختلفة. الهندسة الكهربائية و الصناعية و الكيميائية و الميكانيكية و الكومبيوتر. هذا أعطاني الانطباع المبدئي عن هذه الشركة لأنها تريد مهندسين من تخصصات مختلفة تدربهم و تصنع منهم ما تريد في خلال الثلاث سنوات الأولى من عملهم. قابلنا المهندس محمد الخضري (إنسان في قمه اللباقة و الاحترام) و قدم لنا لمحه بسيطة عن الشركة لمده ساعه تقريباً. و بعد ذلك بدائنا الامتحان المقدم من الشركة ( انجليزي، رياضيات، ميكانيكا، فيزياء كهربائية، أسئلة عامه) استمر الاختبار لمده ساعتين تقريباً. و عندما تم الانتهاء من الاختبار تم تقسيمنا إلى مجموعتين 3 و 4. تم إعطائنا 20 ورقه و مقص و لصق و مسطره. المطلوب كان أن نبني برج لا يقل طوله عن 20 سم و باستطاعته أن يتحمل أكبر عدد من كور الجولف. المغزى من هذا العمل غير الظاهري هو العمل لإنجاز مشروع بمواصفاته المطلوبه ولكن الغير ظاهر هو مهارات العمل و الإتصال مع الاخرين ( الليدرشيب و التيم ورك) و بعد الإنتهاء من هذا الجزء كل فريق قدم عمله على طريقه (البرزنتيشين) . أخذنا بريك لمده نصف ساعه للغذاء و صلاه الظهر. بعد ذلك مباشره تم البدء لعمل المقابلات الشخصيه. في البداية عملت برزنتيشين عن نفسي ( مقدمه، السينيور ديزاين، الكواب) و بعد ذلك تم سؤالي نفس أسئلة المقابلة الهاتفية في خلال 10 -15 دقائق. لم نتطرق إلى الدراسة او مواد التخصص بشكل دقيق لكن تم التحدث عن طبيعة العمل لديهم. عرضوا علي البدء في العمل لديهم في اوروبا الشرقية او البرازيل ( بحسب احتياجهم) و من ثم عرضوا علي منهجيه العمل ( 4 اسابيع عمل و 3 اسابيع إجازة) في اول سنه وخلال السنتين الأخريين سوف يتم تحديدها لاحقاً. المسمى الوظيفي سوف تكون مهندس ميداني و ارفقوا لي بعض الأمثلة التي تشرح مهمه عملي . و في النهاية قالوا لي ننتظر منك الرد في خلال أسبوع سواءً بالموافقة او بالرفض. المقابلة استمرت أكثر من نصف ساعه و الحمد لله على كل حال\nبلغت بالموافقه المبدئيه للعمل في الشركه بعد 4 أيام من المقابله وطلب مني الحضور لبدء الفيلد اكسبوشر لمده أسبوعين مع الكشف الطبي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-z/160911/1", "user": "ENG_WHY_NOT", "ts": 1399596425000, "tid": 160911, "pn": 1}}', 1399596425000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p392249-ee398', 'stk-user1685', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nأشكركم جميعا على ما سطرته أناملكم ومروركم الذي زاد الموضوع أهمية\n\ndr.unknown:\n\nشكرا على مرورك.\n\nلكن صدقني بتكاتفنا وتعاوننا سيكون هناك حل.\n\nأبو عزووز:\n\nشكرا على المرور.\n\nولكن ألا ترى أن البداية من عندنا نحن الطلاب كردة فعل.\n\nسعود الشهراني:\n\nشكرا على مرورك.\n\nصدقني أني كتبت لهم معروض وسأقدمه لهم،ويحتوي بالتفصيل على أسعارهم السابقة\n\nوأسعارهم الحالية.\n\nشحيبر:\n\nشكرا على المرور.\n\nوالله حل وارد.\n\nEE2007:\n\nشكرا على مرورك.\n\nولله رد رجل صامل ( جِدِّي).\n\nS27xxxx:\n\nشكرا لك.\n\nصدقني أني من هؤلاء المدمنين عليه.\n\nولكن قد بلغ السيل الزبى.\n\nرفيع الشان:\n\nشكرا لك.\n\nصدقني سوف نثبت وإياك ذلك.\n\nMaximum:\n\nشكرا لك.\n\nوالقائمة تطول فعلا.\n\nولكن أول الغيث قطرة.\n\nإخواني أرجو تفاعل أكثر وحلول أوسع.\n\nوالله لا يهين المشاركين جميعهم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/72424/10", "user": "user1685", "ts": 1239652373000, "tid": 72424, "pn": 10}}', 1239652373000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518175-ee398', 'stk-khalid348', 'EE 398', 'info', '{"desc": "ماشاء الله ربي يكتب لك ولنا كل مافيه خير والله يرزقك ويرزقنا من واسع فضله وبالرزق الحلال. بصراحة أنا أشوف أن العرض مقبول وممتاز نوعا ما. في الوقت الحالي صار الواحد يقبل بأي راتب ولو كان 6000 الاف. أنا خريج هندسة كهربائية من كلية الجبيل بدرجة البكالوريوس من شهرين تقريبا وعندي خبرة بسيطة على شهادة الدبلوم وسويت تدريب تعاوني في ارامكو و شلمبرجير وقبل اسبوع جاني عرض وظيفي في شركة سندان في الجبيل والفل باكج بعد خصم الـتأمينات 6300 الراتب قليل جدا لكن قبلت العرض بسبب ان هذا العرض هو السلاح الوحيد الي\nأملكه حاليا مع أن راتبي على الدبلوم في شركتي السابقة كان 8500 بعد خصم التأمينات لكن الحمدلله على كل حال وان شاء الله نحصل الأفضل ويكون لنا شأن وبصمة جميلة في هذا البلد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/182457/3", "user": "Khalid348", "ts": 1576876765000, "tid": 182457, "pn": 3}}', 1576876765000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1540769-ee398', 'stk-anonymous34', 'EE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته مسّاكم الله بكل خير جميعًا.. أخواني أنا طالب في جامعة خارج المملكة وعندي فرصة تدريب تعاوني وجاتني أكثر من فرصة وحاب آخذ رأيكم وتوجيهاتكم فيها،\n\nقبلها حاب أوضح تخصصي هو هندسة ميكاترونكس، يجمع بين الميكالنيكال والالكترونيكس وشوي الكتريكال مع بعض ومجالات العمل روبوتيكس، درونز، سيارات كهربائية، أي شيء يجمع بين الإلكتريكال والميكانيكال، أو الإلكترونيكس والميكانيكال.\n\nبخصوص الفرصه الأولى جاتني في أرامكو في قسم ال Geological Operations Dept, Ground Water Div.\n\nحاولت أبحث عن القسم ماعرفت عنه كثير لكن سمعت إنه فيه روبوتيكس وبالتالي طمنني شوي لأن خفت أتدرب في شيء ماله علاقه بتخصصي ونسيت أذكر مقر العمل في الظهران.\n\nالفرصة الثانيه في ينساب في ينبع، المميز بهذي الفرصه إني راح أقدر أتدرب بالكنترول سيستمز وأعرف وأتعلم أكثر عن أنظمة الكنترول والplc وغيرها.\n\nشيء أخير نسيت أذكره، انا إنسان يهمني التوظيف بعد التدريب لو شديت حيلي معهم.. وسألت مهندس في سابك وقال لي إن وضع الشركه مو أفضل شيء وإنه السهم كان ب ١٠٠ وصار ب ٥٠، وصايرين مايوظفون نهائيًا ولو وظفو يوظفون فقط طلاب برنامج السكولارشيب. وجامعتي مو من ضمنها.\n\nبخصوص أرامكو العكس، سمعت إنه عادي يوظفون اللي يكون شاد حيله معهم.\n\nأفتوني إخواني الكرام محتار بصراحه ولكن ما أستغني عن آرائكم وإقتراحاتكم الكريمة.\n\nملاحظه مكان العمل مايهمني.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/187998/1", "user": "anonymous34", "ts": 1767263816067, "tid": 187998, "pn": 1}}', 1767263816067, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1174637-ee398', 'stk-user5643', 'EE 398', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nفي بداية الترم اللي يسبق الكوأب\n\nروح الرابط هذا\nhttp://www2.kfupm.edu.sa/me/Guidelines%20ME%20COOP%20Program.pdf\n\nو اطبع صفحة 15 … و عبي الصفحه و وديها للـ Academic Adviser\nيوقعها لك\n\n( بعد ما تتأكد انك انهيت متطلبات الكوأب و ان شروط التطبيق اللي في الصفحه الرابعه في الرابط اللي فوق تنطبق عليك ) …\n\nبعدين ود الفورم للـ COOP COORDINATOR\n\nبعدها هو بيقولك روح لـ إدارة التدريب … انت روح لهم بيعطونك فورمين صورهم و خلهم معك …\n\nواحد من الفورمين للتقديم على الشركات …\n\nطبعا انت تقدر تقدم على الشركات اللي انت تبيها بلحالك … قدم على موقعهم او ايميلهم\n\nلكن مثلا اللي يبي يطبق في ارامكو …لازم ينتظر الجامعه تفتح التطبيق عن طريق موقعها ( راح يرسلون لك ايميل كل ما تجي شركه للتطبيق ))\n\nاما طلاب الـ ساينس اللي يبون يطبقون في ارامكو يقدمون عن طريق موقع ارامكو و الجامعه ما لها دخل …\n\nفيه شركات مثل شركة الكهرباء و شنايدر الكتريك ممكن انت تقدم عليها عن طريق الموقع على طول … لكن شركات ثانيه زي ارامكو ما ينفع تقدم الا عن طريق الجامعه …\n\nطبعا وقت التسجيل و بعد ما تاخذ الابرفال من ادفايزرك سجل الكورسين me351 & me 350 ( واحد في الصيف وواحد في الترم العادي )\n\nلا تفوتون يوم المهنه لانك ممكن تلقى شركات كثير تاخذك تطبق عندها\n\nهذا ملف من الجامعه حلو انك تقراه عن التطبيق\n\nhttp://www2.kfupm.edu.sa/stutraining/files/coop_guidelines.pdf\n\nو هذا موقع إدارة التدريب فيه معلومات عن التدريب التعاوني و معلومات عن بعض الشركات و الرواتب اللي تعطيها لطلاب الكوأب\nhttp://www1.kfupm.edu.sa/studentaffa...coop/Index.htm\n\nطبعا خلال التطبيق مطلوب منكم 3 ريبورتات و هذي امثله عليها\n\nFirst Progress Report\nhttp://www.m5zn.com/d/?14416022\n\n2nd Progress Report\nhttp://www.m5zn.com/d/?14416023\n\nFinal Progress Report\nhttp://www.m5zn.com/d/?14416024\n\nبالنسبه للـ COOP Plan لا تشيل همها لانها مجرد فورم تعبيه لك الشركه\n\nفكرة الموضوع من الاساس اني اعطيكم امثله لريبورتات ممتازه … اما الخطوات اللي ذكرتها هي اجتهاد مني … اللي حاب يضيف عليها او يعدل عليها حياه الله\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/139645/1", "user": "user5643", "ts": 1359733729000, "tid": 139645, "pn": 1}}', 1359733729000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1036658-ee398', 'stk-starbucks', 'EE 398', 'info', '{"desc": "للتعديل : المعدل 2.40\n\nو أنا شخصيا ماني من أهل الشرقية\n\nولا عندي أي مشكلة في العمل في أي منطقة\n\nو مقابلتي مع أرامكو كانت لقسم في منطقة نائية و ما كان عندي مشكلة\n\nالشركات كثير و قدمت على معظمها كالفارابي و شيفرون الصحراء المجموعة\n\nالمتقدمة و كيمانول\n\nلكن ما من خبر … فيما يختص بالمقابلة فأنا على يقين\n\nبأن وضعي خلالها أكثر من OK\n\nلأنني فاهم التخصص و لله الحمد و أخذت في مشروع التخرج A\n\nو الكوأب A+ و مهارات التواصل جيدة و الانقلش و لله الحمد ممتاز\n\nأنا أرى مشكلة المقابلة تكمن في المقابلين حيث أنهم\n\nيتبنوا قرار ظني … كوني من الغربية هذا يعني أنني لن أستمر معهم\n\nمن وجهة نظرهم … و كان السؤال المشترك لجميع المقابلات\n\nليه ما قدمت على شركات الغربية ؟ لو جاتك الشركة # هل بتسحب علينا ؟\n\nإنتم كذا يا أهل الغربية !! أكيد بتسحب علينا\n\nصراحة لا رغبة لي في إكمال الدراسة\n\nو ميزة هذه الفرصة إني أكون متوظف تابع للمؤسسة\n\nبعد إكمال مدة الإبتعاث … المؤسسة ملزمة بتوظيفي\n\nو أنا الأن على قرابة عام من التخرج … و العطالة ذبحتني من الوريد للوريد\n\nحتى أنني ندمت على أنني لم أضف ترما بعد الفصل الصيفي\n\nلرفع المعدل أكثر\n\nعلاوة على ما سبق … أنا لا أبحث عن المميزات المالية بـعـنـف\n\nبقدر ما أركز على ما يستحقه المهندس و لو قارنت العرض المرفق\n\nلوجدت أنه يقارب عروض الشركات بإستثناء البونص\n\nبل إن العرض مشابه لعروض الكهرباء و التحلية … فهو جيد\n\nلكن ما يحيرني و يشتت تفكيري … غموض المستقبل\nفي حال قبول هذه الفرصة\n\nو ما أحدث به نفسي دائما\n\" ياخي أنت دخلت البترول و إنكرفت عشان حرف الـ م\nو أخرتها بهالمكان !! هذي أقل من طموحك \"\n\nشاكر لك تفاعلك 🌺 🌺 🌺", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/125518/5", "user": "StarBucks", "ts": 1336869331000, "tid": 125518, "pn": 5}}', 1336869331000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1221092-ee398', 'stk-panther', 'EE 398', 'info', '{"desc": "Hi\n\nFirst of all sorry I’m using my job system so I can’t write in Arabic\n\nI took an internship in National Water Company for two months and it is similar to A-Kahraba company in sense that it is owned by the country and they both belong to the ministry of water and electricity.\n\nI don’t know you major but if you are a chemical engineer you will work at Waste Water treatment plant. Your job will be in operation so you operate the plant according to specifications to clean waste water.\nThe company has two branches: waste water treatment and potable water department.\nIf you are a mechanical engineer or electrical engineer you will most probably work in maintenance of a waste water plant.\nThe company is now run by old people from the days of the ministry and now they are hiring youths so you can go up faster than in Al-Kahraba\n\nAbout the salary I don’t remember the exact number but I think as fresh graduate you will get around SR 10,500 as a total package.\n\nHope this will help you all KFUPMers and guests", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/vs/144282/5", "user": "panther", "ts": 1368276234000, "tid": 144282, "pn": 5}}', 1368276234000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473328-ee398', 'stk-vip9311', 'EE 398', 'info', '{"desc": "السلام عليكم جميعا\nاخوكم من المقبولين في شركة مرافق دفعة ٢٠١٦.\nتقريباً صار لي الان في الشركة ٦ أشهر.\nيعلم الله ان هذا المنتدى له فضل كبير في قبولي بالشركة وما قصروا شباب الدفعات السابقة في مساعدتنا، و اقل شي اسويه انه ارد الفضل بمساعدة هذه الدفعة. و بالصدفة عرفت امس من واحد انه في مقابلات راح تكون قريبة لدفعة هذه السنة فقلت خليني ادخل المنتدى اشوف كيف الوضع لانه من فترة ما دخلت. المهم كلامي كثير\n\nنجي للكلام اللي يهمكم.\n\nانا ب اعطيكم كل المعلومات اللي اعرفها و اذا بعد كذا احتجتوا اي شي اسألوا تحت هذا الموضوع و ان شاء الله راح احاول ادخل المنتدى كل يومين و اجاوب كل الاسئلة. ( يا ليت ما تسألوا في الخاص عشان يسير اجاوب في العام و الكل يستفيد لانه الاسئلة راح تتكرر ف افضل اجاوب في العام يصير الكل يشوف. )\n\nطيب خليني ابدأ بطريقة الشركة في التقديم.\n\nشفت انا فوق بعض الشباب تم التواصل معاهم عشان يرسلوا ملفات، هذه اول خطوة. الشركة تفتح التقديم الكترونيا بعد كذا يتم الفرز الكترونيا ومن خلال موظفين الموارد البشرية. يعني اللي معدله كويس و اموره الثانية تمام في امل كبير انه يتواصلوا معاه و يطلبوا منه الملفات. اللي يتواصل معاه غالبا شخص اسمه ايمن ، او محمد، او عبدالرحمن ( للخصوصية ماله داعي اذكر اسمائهم كاملة او ايميلاتهم او ارقامهم و رجاء لحد يطلبها لانه شي خاص )\nالمهم بعد ما تتم هذه الخطوة يتواصلوا معاك بعدها بفترة قد تكون اسبوعين ثلاثة شهر ع حسب المهم بعدها يتواصلوا معاك عشان موعد المقابلة.\n\nنجي للي حالفوا الحظ وتم تحديد مقابلة معاه\n\nالمقابلة صراحة الشركة جدا مهتمة فيها و راح يكون موجود مدير ادارة الموارد البشرية، مدير ادارة Human Capital Development ( ما اعرف ايش بالعربي هههههههه امزح 😁2:المهم هذه ادارة تهتم بالتدريب وكذا ) ايضا مدير من الهندسة و غالبا مدير القسم اللي راح تتوظف فيه و موظف اتش ار ( الزبدة انه اللي بيقابلك مو اي احد، ناس فاهمة و خبرة ) طبعا ما راح يكون عندك اختيار مع اي قسم المقابلة، انت و حظك. بس غالبا راح يكون قسم يحتاجوا فيه تخصصك\n\nالمقابلة نفسها راح تكون شي عام يعني شخصيتك معدلك دراستك مشروع التخرج و مديرك المباشر راح يفصل معاك في مشروع التخرج و الكوأب و مدير الهندسة راح يفصل معاك في التخصص و مواد ٤٠٠ ، يعني بالزبدة استعد كويس و افطر و اشرب قهوة و روح لهم مصحصح لانه المقابلة عندهم نص ساعة على الاقل وما عندهم مقابلة ثانية، يعني من مقابلة وحدة راح يحددوا اما ياخذوك او لا.\n\nع فكرة، الشركة تاخذ من اغلب التخصصات بس الغالب في دفعتنا كانوا هندسة كهرباء، ميكيانيكال و في واحد كيمياء عامة وفي كمان تخصصات ادارية زي محاسبة مالية مدري ايش هذا اللي شفته وفي الدفعة اللي قبلنا اخذوا واحد مدنية و واحد صناعية يعني في تنوع بس حسب اللي شفته انه كهرباء وميكانيكال اكثر شي ( ممكن اكون غلطان في دي المعلومة بس انا انقلكم اللي شايفه )\n\nطبعا بعد المقابلة وسعوا بالكم ، انا اخذوا شهرين تقريبا الين ردوا علينا، مع انهم وقت المقابلة قالوا اسبوعين و نرد. طبعا ازعجتهم اتصالات و كذا بس مافي فائدة. يعني بعد المقابلة لحد يسألني متى يردون من دحين قلت لكم مالكم الا الانتظار ، لحد يسألني دا السؤال يرحم أمكم ^ــ^\n\nطيب نجي للعرض الوظيفي و المميزات المادية\n\nبصراحة مو لاني موظف الان فيها، بس عرضهم حلو جدا مقارنة ب أماكن كثير. يعني راتب أساسي بين ١١-١٢ الف حسب امور ما اعرفها بس اكتشفت انه في تفاوت يعني ناس اعطوهم ١١ الف، ناس ١١٥٠٠ وناس ١٢ الف وممكن ناس اخذت اكثر بس ما اتوقع . طبعا هذا بس راتب اساسي ( هذه لل PDP Engineer ) سواء ميكانيكال او الكتركل، غير المهندسين صراحة ما عندي خبرة\n\nفي عندهم ٢٥٪ بدل سكن + ١٠٠٠ ريال بدل نقل\nبالاضافة عندك تأمين صحي vip من شركة بوبا ( صراحة تأمين ممتاز و يغطي تقريبا كل شي ) للموظف و زوجته اولاده + امه و ابوه بوجود صك اعالة ( سالفة صك الاعالة تافهة و بسهولة تاخذه )\nاضافة الى بونص سنوي ، العام مع الاوضاع الاقتصادية و كذا لكن برضوا جا بونص راتبين و نص وفي السنة اللي قبلها جا بونص ثلاث رواتب ، يعني شي كويس و معقول جدا\n\nالزبدة ينزل لك توتال تقريبا ( بعد خصم التأمينات ) يجي في حسابك حول ١٤ الف و شوية 😂تزيد شوية او تنقص شويات مثل ما قلت لكم حسب راتبك الاساسي\n\nبعدين لل PDP تجيه خلال مدة البرنامج ٤ زيادات، في السنة زيادتين ( كل ستة اشهر يصير فيه تقييم و بناء عليه تجيك زيادة اذا ممتاز زيادة ٧٠٠ اذا جيدجدا ٥٠٠ واذا جيد ٣٠٠ ) طبعا هذه زيادة على الراتب الاساسي، ايضا في زيادة حقت التقييم العام للموظفين ( هذه لحد يسألني فيها لانه فيها كلام كثير ان شاء الله للي ينقبل نشوفه في الشركة و اعطيه العلم ، لانه صار لنا فيها سالفة :shushing_face: )، بس مثل ما قلت هذه غير زيادات ال PDP تجيك وحدة في السنة يعني تقريبا توتال ٦ زيادات 😎\n\nطبعا المهندس يتوظف على وظيفة PDP Engineer بس طبعا يكون في القسم اللي قبله، PDP هذا برنامج زيه زي الشركات الثانية يكون فيه في البداية كورسات بعدين تروح روتيشن على عدة أقسام ووووووو كلام طويل مو وقته الان\n\nخلاص كذا كفاية 🚬 ، اذا انقبلتم ان شاء الله، بنكون زملاء و وقتها اعلمكم الاشياء الثانية لاني تعبت من الكتابة، انا حاولت اتكلم عن كل شي ممكن يدور في ذهنكم ، وترى هذه اول مرة بحياتي اشارك كذا ب منتدى بس والله اني افتكرت حيرتي وقت ما كنت اقدم في الشركة و قلت عهد على نفسي اذا اتوظفت فيها اني اساعد غيري\n\nع فكرة، انا مو من خريجي البترول بس صراحة المنتدى هذا شي جميل 👍\n\nبالتوفيق لكم و ان شاء الله اللي يروح مقابلة يتوفق في الشركة واللي ما يحالفه الحظ ان شاء الله خيرة له و ربي يوفقه في اماكن افضل\n\nو السلام عليكم و رحمة الله و بركاته :man_playing_handball:", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marafiq-2017-pdp/176512/36", "user": "vip9311", "ts": 1495064615000, "tid": 176512, "pn": 36}}', 1495064615000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p27925-ee398', 'stk-qqq', 'EE 398', 'info', '{"desc": "كاتب الرسالة الأصلية ابوتركي\nهههههههه حلوه … انا عارف انك ماتقصد شي غير التنكيت\n\nI know that abu turky understand me 100% because “of corse he is EE\nbut i think the brain for Mr. Dajjah”“sorry Mr.alwalhan”\" is below this level.\nMr.mis-dajjah\nthankyou i agree that \"man kan yoa’meno bellahe wa al-yawm al-aakher fal yagol khairan aw le yasmot\"and i promise you i will put useful topics from now.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/from-coop-student-to-all-kfupm-st/24146/5", "user": "qqq", "ts": 1059375222000, "tid": 24146, "pn": 5}}', 1059375222000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429987-ee398', 'stk-user7794', 'EE 398', 'info', '{"desc": "إعلان عن توفر فرص تدريب تعاوني\n\nتعلن شركة ) Siemens) عن توفر الفرص التدريبية التالية في برنامج التدريب التعاوني وبالتنسيق مع إدارة التدريب في عمادة شؤون الطلاب :\n· الهندسة الكهربائية ( الرياض – جده – المنطقة الشرقية)\n· الهندسة الميكانيكية ( الرياض – المنطقة الشرقية)\n· الهندسة المدنية - الرياض\n· الإدارة (الرياض – جده – المنطقة الشرقية)\n\nعلى الراغبين في التقدم على هذه الفرص التدريبية، إرسال السيرة الذاتية على الإيميل التالي: mahdi.almuammar@siemens.com\n\nإدارة التدريب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/6", "user": "user7794", "ts": 1444371403000, "tid": 170272, "pn": 6}}', 1444371403000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1433091-ee398', 'stk-user8890', 'EE 398', 'info', '{"desc": "Dear Students,\n\nSIEMENS****Training program offers COOP training opportunities to a limited number of high caliber Saudi students who are studying in local universities or abroad. The program has been designed to support senior students to transfer their theoretical knowledge to practical work experience in one of our divisions in three different regions (Riyadh, Jeddah and Eastern Province), as well as achieving university requirements of graduation by completing practical credits.\n\nWe are looking for both engineering and business related majors starting in Jan - Feb 2016. So for now you can share with your students the below applying links as we are not accepting CV’s through direct emails anymore:\n\nApplying link for Electrical, Mechanical and Civil engineers:\n\nhttps://careers.siemens.successfactors.eu/sfcareer/jobreqcareer?jobId=215052&company=Siemens&username =\n\nFor all business related majors:\n\nhttps://careers.siemens.successfactors.eu/sfcareer/jobreqcareer?jobId=215053&company=Siemens&username =\n\nWe are looking forward to receive CV’s of high potential candidates to be part of our training program.\n\nBest Regards,\n\nMahdi Almuammar\n\nRecruitment Manager\n\nSiemens Ltd. SA\n\nBusiness Gate, Building C-1\nAirport Road, Qurtubah District\nP.O. Box 9510, Riyadh 11423\nSaudi Arabia", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/28", "user": "user8890", "ts": 1447332867000, "tid": 170272, "pn": 28}}', 1447332867000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1443501-ee398', 'stk-abu_qasim', 'EE 398', 'info', '{"desc": "إعلان عن توفر فرص تدريب تعاوني\n\nتعلن مجموعة العجمي عن توفر فرص تدريبية في برنامج التدريب التعاوني وبالتنسيق مع إدارة التدريب في عمادة شؤون الطلاب لتخصص الهندسة الكهربائية.\n\no****مميزات التدريب: راتب شهري ( 3500 ريال)\no****مدن التدريب: الرياض- الدمام\n\nعلى الراغبين في التقدم على هذه الفرص التدريبية إرسال سيرهم الذاتية للشركة من خلال البريد الالكتروني التالي:\n\nAbbad.Ahmed@alojaimi.com\n\nإدارة التدريب\nعمادة شؤون الطلاب\nجامعة الملك فهد للبترول والمعادن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/95", "user": "aBu_QaSiM", "ts": 1456845486000, "tid": 170272, "pn": 95}}', 1456845486000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1451362-ee398', 'stk-user9302', 'EE 398', 'info', '{"desc": "السلام عليكم ورحمة الله,\n\nتعلن شركة ايرليكويد العربية عن وجود فرصة تدريب تعاوني لطلاب قسم الهندسة الكهربائية في موقعنا الصناعي بمعمل أرامكو في القريَة (المنطقة الشرقية).\n\nفي حالة رغبتكم بالتسجيل يرجى الرد مع إرفاق السيرة الذاتية.\n\nنتمنى التوفيق للجميع وكل عام وأنتم بخير,\n\nFaisal Alzahrani\nHR Business Partner| ALAR-HQ KSA\nTel: +966-13-8366668 Ex. 1144\nFax: +966-13-8304781\nCell: +966-539176676\nE-Mail: faisal.alzahrani@airliquide.com\nP.O. BOX 2335, Al-Khobar 31952 Saudi Arabia", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/212", "user": "user9302", "ts": 1465384717000, "tid": 170272, "pn": 212}}', 1465384717000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p76179-ee398', 'stk-user765', 'EE 398', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n\nأود أن اعرض هنا موضوع التدريب التعاوني بالنسبة لطلاب كليات المجتمع وبالتحديد كلية المجتمع بحائل … وبالتحديد اكثر طلاب البكالوريس.\n\nومن المعلوم أن كلية المجتمع بحائل بدأت برنامجها لإعطاء درجة البكالوريس في بعض التخصصات مثل علوم الحاسب الآلي والهندسة الكهربائية.\n\nما أود قوله هو أنني أحد طلاب علوم الحاسب الآلي والذين يعتبرون إن شاء الله الدفعة الأولى التي سوف تتخرج بدرجة البكالوريس في علوم الحاسب الآلي. وحيث أن الكلية تعتبر في بدايتها ببرنامج البكالوريس فإنني وغيري ومن زملائي الطلاب نواجه مشاكل كبيره في إيجاد فرص للتدريب التعاوني لدى الشركات. لذلك أود أن أقول لكل من يقرأ هذا الموضوع أن يساعدوني في إيجاد فرصة لدى أي من الشركات المعروفة وخصوصاً في مجال الحاسب الآلي.\n\nكما اتمنى أن ضع رقم هاتفي هنا ولكن لا أعتقد أن إدارة المنتدى تسمح بذلك، لذا فإنني سوف اضع بريدي على الاقل لكي اتواصل مع من يستطيع المساعدة.\nخلاصة القول:\n\nأنا طالب من كلية المجتمع بحائل التابعة لجامعة الملك فهد للبترول والمعادن.\nتخصصي في علوم الحاسب الآلي.\nالتدريب التعاوني يبدأ من الصيف القادم.\n\n[blink]للتواصل بريدي:[/blink]\n\nzmayem@yahoo.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/47980/1", "user": "user765", "ts": 1116792352000, "tid": 47980, "pn": 1}}', 1116792352000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1346360-ee398', 'stk-axis_of_evil', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nيا اخوان الله لا يهينكم احد يعرف طبيعة عمل مركز الملك عبدالله لدراسات وبحوث البترول “kapsarc”\n\nوهل سبق لأحد ان تدرب عندهم coop او توظف\n\nلأني محتار بينهم و بين شركة الكهرب عشان الـكوأب\n\nالتخصص كهرباء 🤓\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/king-abdullah-petroleum-studies-and-research-center/159191/1", "user": "Axis_of_Evil", "ts": 1396266167000, "tid": 159191, "pn": 1}}', 1396266167000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1353695-ee398', 'stk-electric_boy', 'EE 398', 'info', '{"desc": "حسب خبرتي بقسم التوزيع اثناء الكوأب اكثر شيء يركزون علية شغل المحطات وماتشتمل عليه من محولات وسوتشقيرز الخ وممكن يسألونك عن مصطلحات خاصة بالتوزيع مثل الحمل الفعلي والفولتج دروب الخ\nويعتمد على القسم اللي بيوظفونك فيه …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/159951/2", "user": "electric_boy", "ts": 1397785797000, "tid": 159951, "pn": 2}}', 1397785797000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1314408-ee398', 'stk-s200650940', 'EE 398', 'info', '{"desc": "السبب الثاني\n\nالسلام عليكم و رحمة الله و بركاته\n\nأعود إليكم لعرض السبب الثاني من الأسباب التي أراها معوقة للحصول على فرصة وظيفية - المرحلة ما قبل المقابلة - أسرد خلال هذا الموضوع عن تجربة شخصية\n\nالسبب الثاني : طريقة البحث عن الوظيفة\nأعتقد أن مشوار البحث عن الوظيفة ينبغي أن يبدأ قبل التخرج بأشهر قليلة , و لا أقل من أن يبدأ خلال فترة التطبيق الصيفي أو التدريب التعاوني . فمسألة الوقت ضرورية جدا في العملية الوظيفية و كلما بدأت في مرحلة البحث مبكرا كلما زادت فرصك للإلتحاق بالوظيفة و تقليص فترة البطالة بعد التخرج .\n\nكما أن بعض الأشخاص يقتصرون في بحثهم على مجموعة معينة من الشركات و كأنهم يتنبؤون بمستقبلهم و يجزمون بإلتحاقهم بإحدى هذه الشركات التي حددوها مسبقا و بنوا عليها طموحاتهم و أحلامهم فتراهم يكرسون جل وقتهم و ينتظرون ليالي و أيام في إنتظار إتصال من هنا أو إيميل من هناك و لكن تمضي الأيام دون جدوى حتى يستيقض الباحث من أحلامه و يبدأ في إستهداف جميع الشركات ما هب منها و ما دب للتخلص من شبح البطالة الذي لازمه لعدة أشهر .\n\nو لأسلوب البحث و التسجيل أثر في الحصول على الوظيفة , فترى محمد يسجل في مواقع الشركات , كما ترى زيد يكتفي بإرسال معلوماته على إيميلات الشركات و آخر يجوب البلاد و الغفار يوزع في أوراقه هنا و هناك لعله يلتقطها أحد يحن عليه و يوظفه سعودة 😆. و من وجهة نظر شخصية أرى أنه على الباحث عن العمل أن يحدد لنفسه فترة معينة بعد تخرجه يتفرغ فيها كليا لعملية البحث , يستهدف مواقع الشركات و يقدم من خلالها قاطبة , يجمع إيميلات مسؤولي التوظيف و يغرقها بطلبات التوظيف أسبوعيا , يحدد له عدة أيام بالأسبوع ليغزوا مقرات الشركات المتوسطة منها و الصغيرة و يقدم أوراقه يدويا , يتواصل مع الدوائر الحكومية التي قد تساعده في الحصول على وظيفة كمكتب العمل و غرفة الشرقية للتوظيف , يحضر أيام المهنة و أيام التوظيف في مختلف المدن و الجامعات … و حينما يطمئن أنه عمل ما عليه و بذل جل إمكانياته في عملية البحث عليه بقبول أول عرض وظيفي ولو كان بسيطا لإثراء سيرته الذاتية أولا و كمدخول شهري ثانيا . 😏\n\nفي الختام أقول أن الدنيا أرزاق كما ذكر أحد الإخوان , فتوفيق الله لن يكون فقط بالإنضمام لسابك أو أرامكو . خالي خريج البترول بمرتبة الشرف الثانية في قسم الهندسة الكهربائية و بعد تخرجه إضطر للعمل في مصلحة المياه لعدة أشهر و هو حاليا موظف مرموق في أرامكو , و أخي خريج البترول بمرتبة الشرف الثالثة و بعد تخرجه جلس عاطل لمدة 7 أشهر حتى إلتحق بشركة أرامكو . رزقك عند علام الغيوب . موفقون يا أخوة لكل خير و الله يكتبنا من الفائزين برضوانه . 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/154712/16", "user": "s200650940", "ts": 1388782077000, "tid": 154712, "pn": 16}}', 1388782077000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p465321-ee398', 'stk-dr_samir', 'EE 398', 'info', '{"desc": "متطلبات البرنامج التعاوني\n\nالسلام عليكم ورحمة الله وبركاته\n\nPrerequisite: ENGL 214 and the completion of 90 credit hours including all 300 level EE courses.\n\nالدكتور سمير عبدالجواد\nرئيس قسم الهندسة الكهربائية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/75714/10", "user": "Dr_Samir", "ts": 1254146908000, "tid": 75714, "pn": 10}}', 1254146908000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1229237-ee398', 'stk-mr.al-zubaidi', 'EE 398', 'info', '{"desc": "تقدر تاخذها باي سمستر اهم شي تكمل عدد الساعات المطلوبه لاخذ الكوااب او السمر تراينيق مثلا الهندسه الكهربائيه تقدر تاخذ الكواب اذا خلصت 60 ساعه غير الاوريا …\n\nوربي يوفقك ويوفق الجميع …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/145282/3", "user": "Mr.Al-zubaidi", "ts": 1369745762000, "tid": 145282, "pn": 3}}', 1369745762000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1197065-ee398', 'stk-s2xxxxx', 'EE 398', 'info', '{"desc": "و عليكم السلام\nأنت وش تخصصك؟\nلاني انا أعرف واحد تخصصه كهرباء و راح لهم و بعد الواسطة قبلوه كواب بس ان مدة التطبيق 15 اسبوع و المكافاة 1500 و لا فيه ترينينق بلان يقولون انت جيبه من الجامعة و الجامعة تقول انت جيبه من الشركة فعلشان كذا رفض القسم الموافقة على الشركة.\nعاد أنت إذا قدرت تتجاوز هذي الامور كلها الله يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/141716/2", "user": "s2xxxxx", "ts": 1362776353000, "tid": 141716, "pn": 2}}', 1362776353000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1506453-ee398', 'stk-must50', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nمثل ما انتوا شايفين من العنوان، انا طالب دبلوم كلية تقنية تخصص قوى كهربائية و هذا آخر سمستر لي ان شاء الله و راح يكون التدريب التعاوني في الصيف و ماعندي أي خلفية عن التقديم على الشركات و خصوصاً اني طالب دبلوم و الكلية ابد ماتقدم لك خدمة من هالناحية هذه يعطيك الورقه و روح قدم…\n\nالي محتاجه منكم ياشباب ابي شركات اقدم عليهم حق التدريب التعاوني و تكون شركات استفيد منها على الأقل لأني متوهق نوعاً ما و عذروني على الإطالة و شكراً مقدماً", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181082/1", "user": "Must50", "ts": 1551031190000, "tid": 181082, "pn": 1}}', 1551031190000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1506457-ee398', 'stk-gx.r', 'EE 398', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\nبالبداية ابارك لك التخرج , من ناحية الموضوع اللي اعرفه الشركات عندها بالموقع تدريب تعاوني تقدم عليه بعض الشركات فيها وبعضها لا على حسب\nبحكم انك قوى كهربائية شوف سكيكو ولا تحدد شركات معينة قدم على الجميع\nأخر شيء من ناحية الاستفادة اللي أعرفه من إخواننا بالمنتدى أغلب الشركات ما راح تهتم فيك كثير بحكم أنك موب موظف عندهم\nيعني لازم أنت تنشب لهم اذا رحت لازم تهتم بنفسك أكثر وتحاول تستفيد قدر المستطاع …\n\nبالتوفيق والله يحقق لك طموحاتك\n\nأخوك / GX.R", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181082/2", "user": "GX.R", "ts": 1551035838000, "tid": 181082, "pn": 2}}', 1551035838000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p390828-ee398', 'stk-user1443', 'EE 398', 'info', '{"desc": "بالنسبة للكواب تراهم ما يصلحون لانهم يكرفونك كرف والراتب زي ما قلت 3000ريال\n\nبس ما ادري اذا فيها فايدة لان كل المهندسين اللي يتوظفون فيها يشتغلون نفس الشغل ما فيه فرق بين كهرباء ولا بترول", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/72287/15", "user": "user1443", "ts": 1239424756000, "tid": 72287, "pn": 15}}', 1239424756000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1208350-ee398', 'stk-armada', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nأخواني انا طلاب هندسه كهربائيه حاليا اطبق في شركه الصناعات الالكترونيه والكهربائيه EEIC.\n\nالشركه موزع رسمي ومصنع معتمد من شركه شنايدر الكترك.\n\nالشركه متخصصه في صناعه ال motor control centers و switchgears\n\nالي ناوي يتخصص بور او بروتكشن انصح انه يقدم على الشركه\n\nالي حاب يستفسر يتصل على ( انا ما ادخل المنتدى كثير ) 0561155547 محمد او واتس اب 🤠\n\nكل ما في الموضوع اني ابي اساعد وانا جاهز لاي سؤال 🥊\n\nطبعا العرض لطلاب الكوآب فقط لا يشمل السمر تريننق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/142954/1", "user": "armada", "ts": 1365584638000, "tid": 142954, "pn": 1}}', 1365584638000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p844235-ee398', 'stk-user2884', 'EE 398', 'info', '{"desc": "طآلب الكوأب في أرآمـكـو مو معطينـه وجـه !! يعني اضربلك مثال أنا ( واعوذ بالله من كلمة أنا ) أطبق الحين في أرامكـو ،\nيمينا بالله أني أيام كثيـرررة اطفش من الدوام \" أجلس أقرى احوس بالنت أعفس أضيع وقت \" المهم يخلص الدوام !!!\n\nما أقولك ما أستفيد ، ولكن الأستفادة انا اللي افيد نفسي وادور لعمري شغـل !! اروح للمشرف انشب له ، يعطيني شغلة بالممموت !!\n\nعلى عكس الشباب اللي يطبقون بسكيكو ، يقولون يكرفونهم \" وتعلمممو كثيـــر \"\n\nمثل ماقال الأخ يممكن أرامكـو سمعة انك طبقت فيها ولكن ماراح تتعلم شيء ، او بالأحرى ماراح يعلمونك هم شي لازم انت تتعب على عمممرك مثل الناسسس\n\nفي الأخير ، انت فترة تطبيقك كلها شهريـن !! يعني ماتفررق مافيها ذاك الشي الكثيـررر وكلها ريبورت بـو 10 صفحات راح تسلمـه ولا عليه كريدت ! يعني لو تبي نصيحتي شوف لك مكان يريحك مايكرفك \" لاحق ع الكرف \"\n\nاسأل الله التوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/107438/9", "user": "user2884", "ts": 1305373597000, "tid": 107438, "pn": 9}}', 1305373597000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1534693-ee398', 'stk-user10746', 'EE 398', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nاضع بين ايديكم كتاب من اعدادي عام 2017\nوهو ملخص لنشاطات (قطاع التوزيع) في شركة الكهرباء\nكتبته اثناء تدريبي التعاوني في الشركة وكانت مدة التدريب 7 أشهر\n\nأسال الله ان ينفع به، ولعله يكون مرجع لطلاب وممارسي الهندسة الكهربائية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sec-coop-report/184645/1", "user": "user10746", "ts": 1655771822000, "tid": 184645, "pn": 1}}', 1655771822000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1408202-ee398', 'stk-mustafa3', 'EE 398', 'info', '{"desc": "منقووووووول\n\nعزيزي الطالب / عزيزتي الطالبة\nالسلام عليكم ورحمة الله وبركاته\n\nتعلن الشركتان الرائدتان في مجال الطاقة النووية إي دي إف (EDF) وأريفا (Areva) عن فتح مجال التدريب المهني للطلبة السعوديين المتخصصين في شتى مجالات الهندسة في فرنسا خاصة وفي أوروبا عامة لفترات تتراوح بين 3 إلى 7 أشهر في منشئاتهما النووية والهندسية في فرنسا وألمانيا.\n\nيأتي هذا التدريب ضمن مضي الشركتين في المشروع النووي السلمي السعودي الذي تقوده مدينة الملك عبدالله للطاقة الذرية والمتجددة (KACARE).\n\nتم استضافة أول دفعة تدريب لعدد يقارب 40 طالب سعودي في يونيو 2014 وتكللت بالنجاح بفضل الله، حيث أن خريجي التدريب لدى إي دي إف وأريفا تم إعطاؤهم الأولوية في التوظيف في شركة الكهرباء السعودية ، بالإضافة إلى إثارة الاهتمام للعديد من الشركات الصناعية فيهم.\n\nيجدر بالذكر أن إي دي إف مملوكة للحكومة الفرنسية بنسبة 85% المشغل الرئيسي للكهرباء في فرنسا، تملك وتشغل 58 مفاعل نووي في فرنسا، عوضاً عن نشاطاتها في مجال الطاقة في أكثر من 20 دولة، وأريفا المملوكة بنسبة مماثلة للدولة تخدم ما يفوق 300 مفاعل نووي في العالم في شتى الطرق كالتزويد بالوقود، والتكنلوجيا النووية، وإعادة تدوير الوقود.\n\nللمزيد من المعلومات:\nwww.edf.com\nwww.areva.com\n\nللتواصل والتقديم على التدريب:\nعبدالله بن إبراهيم الحميد\nمدير التسويق والعلاقات العامة\nإي دي إف ، الرياض\nAbdullah.ALhumaid@edf\\-me.com\n00966599955510\n00966115101109\n\nوالله ولي التوفيق ،،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/edf-areva/166685/1", "user": "Mustafa3", "ts": 1414522993000, "tid": 166685, "pn": 1}}', 1414522993000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1071015-ee398', 'stk-user1338', 'EE 398', 'info', '{"desc": "^\n^\nنعم فيه سمر وفيه كوأب\n\nوالمكافأه 4500 لطلاب البترول وباقي الجامعات 3500\n\nطريقة التقديم فيه بموقع الشركة اعتقد بس قدم بدري او اذا تعرف احد بالشركة يسنعك\n\nالصيفي هذا المتدربين كثير تقريبا 50 واحد من التخصصات الهندسه اغلبهم صناعي وكهرب اذا مو كلهم\n\nع العموم هذا رقم الشركه 012201350\n\nتحويلة احد الموظفين بالاتش ار وله علاقة بالتدريب راح يفيدك ان شاء الله 1347 اسمه هيثم القرطون", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/129141/7", "user": "user1338", "ts": 1343048453000, "tid": 129141, "pn": 7}}', 1343048453000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p396839-ee398', 'stk-user5089', 'EE 398', 'info', '{"desc": "والله يا شباب اشوفكم ما تنصحون اخذ الكواب مع ارامكو.\nبس ما ادري ويش رايكم في الكواب حق ارامكو بالنسبة للمهندس الصناعي لأن الكلام الي فوق احس انه موجه للمهندس المكانيكي والكهربائي.\nطيب هل خبرة السبعة شهور تنفعني بحيث ان الكواب عندي اخر ترم يعني اذا انت تدربت في ارامكو يمكن يكون للشركة الي انت متقدم لها تنظر لك بنظرة خاصة\n\nارجو الرد على جميع استفسارتيي لا هنتم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/72756/4", "user": "user5089", "ts": 1240691362000, "tid": 72756, "pn": 4}}', 1240691362000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1326753-ee398', 'stk-_16', 'EE 398', 'info', '{"desc": "شركة الكهرباء السعودية تعطيك 2000 ريال\nشركة الخطوط السعودية تعطيك 3000ريال\nشركة حدادة ومقرها المدينة الصناعية رقم 1 تعطيك 3000ريال\nلايوجد عندي ارقام للشركات لكن بامكانك تدور عليها في الانترنت شركة الكهرباء تتصل على ادارة الغربية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/156504/2", "user": "_16", "ts": 1391598709000, "tid": 156504, "pn": 2}}', 1391598709000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1284951-ee398', 'stk-hummer_4_ever', 'EE 398', 'info', '{"desc": "السلام عليكم ورحمة الله و بركاته\nاللي اعرفه من اخوياي المهندسين اللي كانوا شغالين بالشركة وقت اللي كنت كواب\n2012 June 2012-December\nبدل سكن 30% من الراتب الأساسي\nبدل مواصلات 1950 أو سيارة في الغالب ford explorer\nتأمين طبي شركة بويا (ممكن تغيرت الآن)\n500 ريال ( البعض كان يسميها بدل غلاء معيشة )\n\nملاحضة هامة : اللي اعرفهم تخصصاتهم EE , Cise\nهل تغيرت الآن العلم عن الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/151916/10", "user": "hummer_4_ever", "ts": 1384033186000, "tid": 151916, "pn": 10}}', 1384033186000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p95312-ee398', 'stk-yasser_84', 'EE 398', 'info', '{"desc": "thank you for your support Mr. رحال\n\nمهندس كهربائي\nI guess you are right, I should have talked to the dean of student affairs even before posting this thread…\nbut I just wanted to share my situation (and all non-Saudi students’ situation) with my brother students and see if I have the right to ask for Student Affairs help or not.\n\nRegards", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/why-is-coop-required-for-foreigners/50311/4", "user": "yasser_84", "ts": 1145321720000, "tid": 50311, "pn": 4}}', 1145321720000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1372492-ee398', 'stk-user7448', 'EE 398', 'info', '{"desc": "السلام عليكم\n\nشباب انا تخصصي هندسة كهربائية وعندي تدريب تعاوني الصيف هذا هل فيه احد عنده معلومية عن الشركات الي توفر فرص تدريب تعاوني في جده وانا راح اتواصل معاهم .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/161818/1", "user": "user7448", "ts": 1401177497000, "tid": 161818, "pn": 1}}', 1401177497000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1125180-ee398', 'stk-user8229', 'EE 398', 'info', '{"desc": "الشركات الموجوده في يوم المهنة الترم هذا\nشركة الكهرب من بينها وتطلب طلاب كوأب وتعطي كل التخصصات 2000 ريال\nهذا اذا كنت تقصدها\n\nعلى العموم اغلب الفرص تشوفها هنا\nhttp://cday.kfupm.edu.sa/opps_search.aspx", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cisco/135536/2", "user": "user8229", "ts": 1354026700000, "tid": 135536, "pn": 2}}', 1354026700000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1481310-ee398', 'stk-alasad', 'EE 398', 'info', '{"desc": "السلام عليكم\nانا طبقت في شركة سابك (صدف)\nفي قسم SMD\nزملاء القسم جميعهم متعاونين بشكل جدا جميل\nمن ناحية اهتمام وتدريب فاستفدت بشكل خيالي كمية من المعرفة هائلة والتعامل مع االمشكلات وحلها\nكبيئة عمل جدا جميلة وتساعدك في التطوير\nطبعا انا مهندس كهرباء فأخدت روتيشن على جكيع المصانع فترة الكواب\nواتمنى لو يحصل لي نصيب واشتغل معاهم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/158102/8", "user": "alasad", "ts": 1507110461000, "tid": 158102, "pn": 8}}', 1507110461000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1172134-ee398', 'stk-amat_24', 'EE 398', 'info', '{"desc": "اها يصير قصدك Quality of Power consumption\n\nquality of consumption وليس consumption of quality 😁\n\nبس صار الexperience فيه تكرار، بينما تقدر تختصر وتضيف تفاصيل\n\nهذا اقتراح لاعادة صياغة الفقرة كاملة:\n\nAl Joudah Contracting Company - Hail, Saudi Arabia\nCo-op Engineer (Sep 2012 - Jan 2013)\nJoined Al Joudah as a trainee as per my BSc. requirements, where I was assigned to Hail Domestic Airport for the period of 7 months. During that period, the hands-on training gave me the opportunity to apply many of the skills which I had learned during my studies\n\nAs a member of an engineering team, I performed a case study to determine the peak hours at which the electric power consumption is at its highest, and attempted to study the reasons behind this from the quality point of view. To do so, we spent 3 months collecting data while heavily utilizing the Minitab numerical analysis software\n\nتاكد من اسم الشركة بالظبط لانه هذا اللي حصلته بعد سيرش سريع\n\nبالمناسبة، في حال انك كتبت عنوان رئيسي للprojects، الفقرة الثانية من اللي فوق تعتبر بروجكت وتقدر تكتبها هناك\n\nانصحك تعرضها على مهندس (او طالب) electrical power engineering لغته ممتازة لاني ممكن اكون غلطت في الترجمة او المصطلحات\n\nبالتوفيق 🌹🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/139056/44", "user": "amat_24", "ts": 1359403986000, "tid": 139056, "pn": 44}}', 1359403986000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1483251-ee398', 'stk-acheng', 'EE 398', 'info', '{"desc": "\"\nإعلان عن توفر فرص تدريب تعاوني\n\nتعلن شركة ساتورب عن توفر فرص تدريب تعاوني وبالتنسيق مع إدارة التدريب بعمادة شؤون الطلاب للتخصصات التالية:\n\n· الهندسة الكيميائية\n\n· الهندسة الكهربائية\n\n· الهندسة الميكانيكية\n\n· هندسة نظم التحكم والقياس\n\n· نظم المعلومات الإدارية\n\nعلى الراغبين في التقدم على هذه الفرص التدريبية، إرسال السيرة الذاتية للشركة على البريد الالكتروني:\n\nSameer.Buzilfah@satorp.com\n\nإدارة التدريب\n\nعمادة شؤون الطلاب\n\nجامعة الملك فهد للبترول والمعادن\"", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/172-173-181/177905/16", "user": "ACHEng", "ts": 1510470180000, "tid": 177905, "pn": 16}}', 1510470180000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
